using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json.Linq;

namespace WeatherService.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class WeatherForecastController : ControllerBase
    {
        private static readonly HttpClient client = new HttpClient();

        // A simple GET endpoint that fetches weather data from an API and adjusts the color scheme of the app background based on the current temperature.
        [HttpGet]
        public async Task<IActionResult> Get(string location)
        {
            try
            {
                HttpResponseMessage response = await client.GetAsync("https://api.openweathermap.org/data/2.5/weather?q=" + location);
                response.EnsureSuccessStatusCode();

                string responseBody = await response.Content.ReadAsStringAsync();

                JObject jsonResponse = JObject.Parse(responseBody);

                double temperatureInKelvin = (double)jsonResponse["main"]["temp"];
                int temperatureInCelsius = ConvertToCelsius(temperatureInKelvin);

                string colorScheme = GetColorSchemeBasedOnTemperature(temperatureInCelsius);

                return Ok(new { location, temperature = temperatureInCelsius, colorScheme });
            }
            catch (HttpRequestException ex)
            {
                return BadRequest(ex.Message);
            }
        }

        // Converts Kelvin to Celsius
        private static int ConvertToCelsius(double temperatureInKelvin)
        {
            return (int)(temperatureInKelvin - 273.15);
        }

        // Dummy method, replace this with your own logic for color scheme based on temperature
        private static string GetColorSchemeBasedOnTemperature(int temperatureInCelsius)
        {
            if (temperatureInCelsius < 0) return "cold";

            if (temperatureInCelsius > 30) return "hot";

            return "moderate";
        }
    }
}
