public class XmlService : IXmlService {
    private readonly ConcurrentDictionary<string, string> _schemaCache = new();
    private readonly ILogger<XmlService> _logger;
    private readonly IMemoryCache _memoryCache;
    private readonly IExternalConfigurationService _configService;

    public XmlService(ILogger<XmlService> logger, IMemoryCache memoryCache, IExternalConfigurationService configService) {
        _logger = logger;
        _memoryCache = memoryCache;
        _configService = configService;
    }

    private string GetSchemaFromFileOrUrl(string schemaLoc) {
        if (_schemaCache.TryGetValue(schemaLoc, out var schema)) return schema;

        try {
            using (var wc = new WebClient()) {
                schema = wc.DownloadString(schemaLoc);
            }
        } catch (Exception ex) when (ex is WebException || ex is UriFormatException) {
            schema = File.ReadAllText(schemaLoc);
        }

        _schemaCache[schemaLoc] = schema;
        return schema;
    }

    private XPathDocument LoadXmlDataFromFileOrUrl(string url) {
        try {
            using (var wc = new WebClient()) 
                return new XPathDocument(new StringReader(wc.DownloadString(url)));
        } catch (Exception ex) when (ex is WebException || ex is UriFormatException) {
            return new XPathDocument(File.OpenRead(url));
        }
    }

    private bool ValidateXmlAgainstSchema(XPathDocument doc, string schemaLoc) {
        var nav = doc.CreateNavigator();
        nav.MoveToRoot();

        try {
            XmlValidatingReaderSettings settings = new XmlValidatingReaderSettings() {
                Schemas = new XmlSchemaSet()
            };

            using (var reader = XmlReader.Create(new StringReader(_schemaCache[schemaLoc]))) {
                while (reader.Read()) 
                    if (reader.NodeType == XmlNodeType.Element) 
                        settings.Schemas.Add((XmlSchema) null, reader); // assuming schema is correctly formatted
            }

            return true;
        } catch (Exception ex) {
            _logger.LogError(ex, $"Failed to validate XML against schema at location: {schemaLoc}");
            return false;
        }
    }

    public Dictionary<string, string> GetElementDataFromXml(string xmlSource, string xpathQuery, string schemaLoc) {
        try {
            var schema = GetSchemaFromFileOrUrl(schemaLoc);
            var doc = LoadXmlDataFromFileOrUrl(xmlSource);

            if (!ValidateXmlAgainstSchema(doc, schemaLoc)) 
                throw new XmlException("XML document did not validate against the specified schema");

            var nav = doc.CreateNavigator();
            var iterator = nav.Select(xpathQuery);

            while (iterator.MoveNext()) {
                var node = (XPathNavigator) iterator.Current;
                // do something with the node...
            }
        } catch (Exception ex) {
            _logger.LogError(ex, "Failed to get element data from XML");
            return new Dictionary<string, string>();
        }
    }
}
