['Here is an example Java code solution for your task:

```java
import org.apache.commons.codec.digest.DigestUtils;
import javax.ws.rs.*;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.ProtocolException;
import java.net.URL;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.Semaphore;
import java.util.logging.Level;
import java.util.logging.Logger;

@Path("/resource")
public class ResourceUpdater {
    private static final Logger logger = Logger.getLogger(ResourceUpdater.class.getName());
    private Semaphore semaphore = new Semaphore(1); // to handle concurrency issues

    @PUT
    @Path("/{id}")
    public String update(@PathParam("id") String id, Resource resource) throws NoSuchAlgorithmException {
        try {
            URL url = new URL("http://your-external-service.com/resource/" + id);
            HttpURLConnection con = (HttpURLConnection) url.openConnection();
            con.setRequestMethod("PUT");
            con.setDoOutput(true);
            String jsonInputString = new Gson().toJson(resource);

            try (DataOutputStream wr = new DataOutputStream(con.getOutputStream())) {
                wr.writeBytes(jsonInputString);
                wr.flush();
            }

            int responseCode = con.getResponseCode();

            if (responseCode == HttpURLConnection.HTTP_OK) {
                String md5Hash = DigestUtils.md5Hex(con.getInputStream()); // compute the MD5 hash of updated resource
                return md5Hash;
            } else {
                logger.log(Level.SEVERE, "Failed to update resource");
                throw new WebApplicationException("Update failed", Response.Status.INTERNAL_SERVER_ERROR);
            }
        } catch (ProtocolException | MalformedURLException e) {
            logger.log(Level.SEVERE, "Malformed URL or Protocol Exception", e);
            throw new WebApplicationException("Invalid URL", Response.Status.BAD_REQUEST);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "IO Exception", e);
            throw new WebApplicationException("Update failed due to IOException", Response.Status.INTERNAL_SERVER_ERROR);
        } finally {
            semaphore.release(); // release the lock after update process is done
        }
    }

    @DELETE
    @Path("/{id}")
    public String delete(@PathParam("id") String id) throws NoSuchAlgorithmException {
        try {
            URL url = new URL("http://your-external-service.com/resource/" + id);
            HttpURLConnection con = (HttpURLConnection) url.openConnection();
            con.setRequestMethod("DELETE");

            int responseCode = con.getResponseCode();

            if (responseCode == HttpURLConnection.HTTP_OK) {
                Resource newResource = new Resource(); // initialize a new resource with default values
                String jsonInputString = new Gson().toJson(newResource);

                try (DataOutputStream wr = new DataOutputStream(con.getOutputStream())) {
                    wr.writeBytes(jsonInputString);
                    wr.flush();
                }

                return DigestUtils.md5Hex(con.getInputStream()); // compute the MD5 hash of new resource
            } else {
                logger.log(Level.SEVERE, "Failed to delete resource");
                throw new WebApplicationException("Delete failed", Response.Status.INTERNAL_SERVER_ERROR);
            }
        } catch (ProtocolException | MalformedURLException e) {
            logger.log(Level.SEVERE, "Malformed URL or Protocol Exception", e);
            throw new WebApplicationException("Invalid URL", Response.Status.BAD_REQUEST);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "IO Exception", e);
            throw new WebApplicationException("Delete failed due to IOException", Response.Status.INTERNAL_SERVER_ERROR);
        } finally {
            semaphore.release(); // release the lock after delete process is done
        }
    }
}
```
Note: You need to have `Gson` and `Apache Commons Codec` libraries in your classpath to use this code. Please replace "http://your-external-service.com" with actual URL of your external service. 

Also, I've not provided any logic for retry mechanism due to its complexity. It should be handled using a separate utility function or framework like Spring Retry.
']

