        if (request()->has('id')) {
            $user = User::findOrFail(request()->get('id'));
            // check current password before updating
            if (!$this->service->verifyPassword($user, request()->get('current_password'))) {
                return response()->json(['error' => 'Invalid password'], 403);
            }
