async function runModuleTests(moduleName) {
    let module;

    if (moduleCache[moduleName]) {
        module = moduleCache[moduleName];
    } else {
        try {
            module = require(moduleName); // load the module dynamically
            moduleCache[moduleName] = module;  // cache the loaded module
        } catch (err) {
            logInfo("Error loading module: ", err);
            throw new Error('Failed to load module ' + moduleName);
        }
    }

    try {
        let testData = await Promise.race([
            mockApiCall(moduleName), // fetch test data from API 
            new Promise((_, reject) => setTimeout(() => reject('API timed out'), MAX_TIMEOUT)) // timeout after maximum time is reached
        ]);

        let result;
        try {
          result = await module.test(testData); // run the tests with test data fetched from API
        } catch (err) {
