        } else {
            logInfo({moduleName, result: 'FAILED'});
            // additional handling for test failures goes here
        }

    } catch (err) {
        if (RETRY_ATTEMPTS > 0) {
            RETRY_ATTEMPTS--;
            logInfo("Retrying tests due to: ", err);
            return runModuleTests(moduleName); // retry the test after a delay
