    @RowsPerPage INT = 50 
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        -- Parse Supervisor IDs into a table for IN clause filtering.
        DECLARE @SupTable TABLE (ID VARCHAR(25))
        INSERT INTO @SupTable SELECT value FROM STRING_SPLIT(@SupervisorIDs, ',')

        -- Select data based on given parameters, using precomputed index if available.
