<?php
require 'vendor/autoload.php';
use \Firebase\JWT\JWT;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;
use Predis\Client as RedisClient;

class SessionService {
    private $redisClient;
    private $logger;
    private $authApiClient;
    private $jwtKey;

    public function __construct(RedisClient $client, Logger $logger, AuthAPIClient $apiClient) {
        $this->redisClient = $client;
        $this->logger = $logger;
        $this->authApiClient = $apiClient;
        // This should be securely stored and fetched from secured storage like environment variables or key management services
        $this->jwtKey = 'your_jwt_secret'; 
    }

    public function createSession($userCredentials) {
        try {
            if ($this->authApiClient->validateUser($userCredentials)) {
                $payload = array(
                    "iss" => "http://example.org", // issuer
                    "iat" => time(),  // issued at
                    "exp" => time()+3600, // expiration time in seconds (1 hour)
                    "data" => $userCredentials['username'] // User Data Here
                );
                $jwt = JWT::encode($payload, $this->jwtKey);
                $sessionId = $this->redisClient->incr('next_session_id');
                $this->redisClient->hset('sessions', $sessionId, $jwt);

                $this->logger->info("Session Created", ['sessionId' => $sessionId]);
                return $jwt;
            } else {
                $this->logger->warning("Invalid User Credentials", $userCredentials);
                throw new Exception('Invalid credentials');
            }
        } catch(Exception $e) {
            $this->logger->error("Error Creating Session: ".$e->getMessage(), ['exception' => $e]);
            throw $e;
        }
    }

    public function validateSession($jwtToken) {
        $decoded = JWT::decode($jwtToken, $this->jwtKey, array('HS256'));

        // Check if the session exists and is valid in Redis
        $sessions = $this->redisClient->hgetall('sessions');
        if (in_array($jwtToken, $sessions)) {
            $this->logger->info("Session Validated", ['sessionId' => array_search($jwtToken, $sessions)]);
            return true;
        } else {
            $this->logger->warning("Invalid Session Token", ['token' => $jwtToken]);
            throw new Exception('Invalid session token');
        }
    }

    public function fallbackToDatabase($apiIsDown) {
        // Handle the case when external API is down, retrieve or save to database instead.
        if ($apiIsDown) {
            $this->authApiClient = new DatabaseAPIClient();
            $this->logger->warning("Fallback to Database");
        }
    }
}
?>
```

For logging, the `monolog/monolog` library is used here. Similarly, JSON Web Tokens (JWT) are handled by `firebase/php-jwt`, and Redis client is handled by `predis/predis`. 

