['```java
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.web.bind.annotation.*;
import java.util.concurrent.*;
import static java.lang.System.currentTimeMillis;
import static java.util.stream.IntStream.range;

@RestController
public class TransactionService {
    private final ObjectMapper mapper = new ObjectMapper();
    private final ConcurrentMap<String, Category> categories = new ConcurrentHashMap<>();
    private final BlockingQueue<Transaction> transactionsQueue = new LinkedBlockingDeque<>(10_000); // 10k transactions in memory max
    private final ExecutorService executor;

    public TransactionService() {
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        startConsuming();
    }

    @PostMapping("/transaction")
    void receiveTransaction(@RequestBody String transactionJson) {
        executor.submit(() -> {
            try {
                Transaction transaction = mapper.readValue(transactionJson, Transaction.class);
                if (currentTimeMillis() / 1000L - transaction.getTimestamp() <= 300 // 5 minutes old
                        && transaction.getCategory().equals("specific category") // specific category
                        && transaction.getWeightedSum() > 100) { // weighted sum greater than 100
                    transactionsQueue.put(transaction);
                }
            } catch (Exception e) {
                System.err.println("Failed to deserialize transaction: " + transactionJson + ". Reason: " + e.getMessage());
            }
        });
    }

    @GetMapping("/metrics")
    Object getMetrics() {
        return categories; // returns the highest weightedSum encountered per category, along with the corresponding transactionId 
    }

    private void startConsuming() {
        executor.submit(() -> {
            while (true) {
                try {
                    Transaction transaction = transactionsQueue.take();
                    categories.compute(transaction.getCategory(), (k, v) -> {
                        if (v == null || v.getWeightedSum() < transaction.getWeightedSum())  // update category metric with new highest weightedSum and corresponding transactionId 
                            return new Category(transaction.getId(), transaction.getWeightedSum());
                        else
                            return v;
                    });
                } catch (Exception e) {
                    System.err.println("Failed to process transaction: " + e.getMessage());
                }
            }
        });
    }

    static class Transaction {
        private String id, category;
        private long timestamp;
        private double weightedSum;

        // getters and setters
    }

    static class Category {
        private final String transactionId;
        private final double weightedSum;

        Category(String transactionId, double weightedSum) {
            this.transactionId = transactionId;
            this.weightedSum = weightedSum;
        }

        // getters 
    }
}
```

This implementation uses Spring Boot for REST API, Jackson for JSON deserialization, and a simple ExecutorService to handle asynchronous processing of incoming transactions without blocking the main thread. A ConcurrentHashMap is used for storing category metrics concurrently. The BlockingQueue limits the number of transactions in memory and backpressure strategies are automatically applied by LinkedBlockingDeque when queue is full.

For unit testing, Junit 5 with Mockito can be used to mock external dependencies like REST API clients and JSON deserializers. Assertions can be made on service behavior under different scenarios such as invalid JSON formats or transaction age limit violations. 

This code does not include resource management strategies for concurrent transactions nor memory usage, which should be added based on specific performance requirements and system limits. 

Please note that this is a simplified version of the problem with a lot of assumptions and simplifications to focus more on solving the main problem in hand. Actual implementation might need additional components like an external transaction data source or error handling strategies.
']

