    bool isSecondaryAttackReady = true;

    void PrimaryAttack() {
        // Perform primary attack logic here
    }

    void SecondaryAttack() {
        // Perform secondary attack logic here
    }

    void Attack(bool isPrimary) {
        if (isPrimary && isPrimaryAttackReady) {
            PrimaryAttack();
            isPrimaryAttackReady = false;
            std::thread t([&]() {
                // Cooldown period for primary attack, e.g., 5 seconds
                std::this_thread::sleep_for(std::chrono::seconds(5));
                isPrimaryAttackReady = true;
            });
            t.detach();
        } else if (!isPrimary && isSecondaryAttackReady) {
            SecondaryAttack();
            isSecondaryAttackReady = false;
            std::thread t([&]() {
                // Cooldown period for secondary attack, e.g., 5 seconds
                std::this_thread::sleep_for(std.chrono::seconds(5));
                isSecondaryAttackReady = true;
            });
            t.detach();
        } else {
            // Attack not ready
        }
    }
};
