module FilenameGenerator {
    // Initialize the mutex for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    function char* generateFilename(char* baseName, char* directory) {
        pthread_mutex_lock(&lock); // Lock the mutex to avoid race conditions

        char *filename = malloc(strlen(baseName) + 20); // Allocate memory for filename
        strcpy(filename, baseName); // Copy basename into filename

        int counter = 1;
        while (fileExists(directory, filename)) { // Check if the file exists already
            sprintf(filename, "%s-%d", baseName, counter++); // If it does, append a number to the end of the name
        }

        pthread_mutex_unlock(&lock); // Unlock mutex after operation

        return filename;
    }

    function bool fileExists(char* directory, char* filename) {
        char *fullPath = malloc(strlen(directory) + strlen(filename) + 2); // Allocate memory for full path

        sprintf(fullPath, "%s/%s", directory, filename); // Create full file path

        struct stat buffer;   
        return (stat(fullPath, &buffer) == 0); // Check if the file exists with system call
    }
}
