    public async Task ProcessStreamAsync(byte[] data)
    {
        var policy = Policy
            .Handle<Exception>()
            .WaitAndRetryForeverAsync(_ => TimeSpan.FromSeconds(5), (exception, timeSpan, retryCount, context) => 
                _logger.LogWarning($"Error occurred while processing stream: {exception.Message}. Retrying..."));

        await policy.ExecuteAsync(async () =>
        {
            using var connection = _connectionFactory.CreateConnection();
