            // Publish data to RabbitMQ queue 
            channel.QueueDeclare("myqueue", durable: true, exclusive: false, autoDelete: false);
            channel.BasicPublish(string.Empty, "myqueue", null, body: data);

            // Store data in MongoDB 
            var collection = _mongoDb.GetCollection<MyDataObject>("mycollection");
