['The problem you are asking requires extensive knowledge in different fields of software development like network programming, database interaction, concurrency control, dependency management etc. However, a general guideline can be given for a C# service component responsible for securely generating and storing MD5 hashes of user-provided strings in a remote, scalable database.

```Csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Polly;
using RabbitMQ.Client;

public class HashingService : IHashingService
{
    private readonly IExternalApiClient _externalApiClient;
    private readonly IRabbitMqConnection _rabbitMqConnection;
    private readonly IDbContext _dbContext;

    public HashingService(IExternalApiClient externalApiClient, IRabbitMqConnection rabbitMqConnection, IDbContext dbContext)
    {
        _externalApiClient = externalApiClient ?? throw new ArgumentNullException(nameof(externalApiClient));
        _rabbitMqConnection = rabbitMqConnection ?? throw new ArgumentNullException(nameof(rabbitMqConnection));
        _dbContext = dbContext ?? throw new ArgumentNullException(nameof(dbContext));
    }

    public async Task HashAndStoreAsync(string input)
    {
        if (string.IsNullOrWhiteSpace(input))
            throw new ArgumentException("Input cannot be null or empty");

        var hash = ComputeHash(input);

        await _rabbitMqConnection.PublishMessageAsync(hash);
        // If the message is not ack'd within a reasonable timeframe, the hashing service can consider it failed and handle it accordingly
        Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)))
            .ExecuteAsync(() => 
                _externalApiClient.SendDataAsync(_dbContext.InsertHashEntry(hash)) // Assuming the API also interacts with a database.
            ); 
    }

    private string ComputeHash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
                sb.Append(hashBytes[i].ToString("X2"));

            return sb.ToString();
        }
    }
}
```

This example does not cover all requirements like load balancing, error handling, logging and monitoring, resource management, performance optimization etc., but it provides a basic structure for designing such a service. You'd need to refine it further based on your specific requirements. 

