    /// Levels of log entries to be retrieved - Info, Debug or Error.
    #[clap(short, long, default_value = "Error")]
    level: LogLevel,
}

#[derive(Debug, Clone, Copy)]
enum LogLevel {
    /// Represents an error condition.
    Error = 0,

    /// Designates potentially harmful situations.
    Warn = 1,

    /// Represents informational messages that highlight the progress of application at coarse-grained level.
    Info = 2,

    /// Fine grained informational events to further refine application processes.
    Debug = 3,
