['Here's a basic framework for the library:

```rust
use std::fs;
use std::io;
use std::collections::HashMap;
use std::sync::{Mutex, Arc};
use std::env;
use serde_json::Value;

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

#[derive(Debug)]
pub struct DirectoryManager {
    dirs: Mutex<HashMap<String, String>>,
}

impl DirectoryManager {
    pub fn new() -> Self {
        DirectoryManager { dirs: Mutex::new(HashMap::new()) }
    }

    pub fn create_directory(&self, name: &str) -> Result<()> {
        let mut dirs = self.dirs.lock().unwrap();
        if !dirs.contains_key(name) {
            fs::create_dir_all(name)?;
            dirs.insert(name.to_string(), name.to_string());
            env::set_var("PATH", &dirs[name]);
        }
        Ok(())
    }
}

#[derive(Debug)]
pub struct ConfigurationManager {
    config: Mutex<Value>,
}

impl ConfigurationManager {
    pub fn new() -> Self {
        ConfigurationManager { config: Mutex::new(Value::Null) }
    }

    pub fn load_config(&self, path: &str) -> Result<()> {
        let file = fs::File::open(path)?;
        let reader = io::BufReader::new(file);
        let config: Value = serde_json::from_reader(reader)?;
        *self.config.lock().unwrap() = config;
        Ok(())
    }
}
