    if (!fsa->states) {
        pthread_rwlock_unlock(&fsa->lock);
        return NULL; // Return NULL on memory allocation failure...
    }

    // Update the state list and resolve dependencies...
    for (int i = 0; i < numCurrentStates; ++i) {
        fsa->states[i] = currentStates[i];
    }

    DependencyGraph* graph = createDependencyGraph(fsa->states, fsa->numStates);
    resolveDependencies(graph);

