            _key = key;
            _iv = iv;
        }

        public async Task LoadDataAsync<T>(string filePath) where T : class
        {
            using (FileStream sourceStream = new FileStream(filePath,
                FileMode.Open, FileAccess.Read, FileShare.None, 4096, true))
            {
                Aes aesAlgorithm = Aes.Create();
                ICryptoTransform decryptor = aesAlgorithm.CreateDecryptor(_key, _iv);

                using (CryptoStream cryptoStream = new CryptoStream(sourceStream, decryptor, CryptoStreamMode.Read))
