```c
#include <stdio.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>
#include <sys/stat.h>

typedef struct {
    char base_name[256];
    char directory[256];
} file_data;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore;

void* check_and_create(void *arg) {
    file_data *fd = (file_data*) arg;

    char fullpath[512];
    sprintf(fullpath, "%s/%s", fd->directory, fd->base_name);

    sem_wait(&semaphore); // Locking for atomicity
    pthread_mutex_lock(&mutex);

    if (access( fullpath, F_OK ) != -1) { 
        printf("File exists: %s\n", fullpath);
        rename(fullpath, "newName"); // Rename operation
    } else {
        FILE *file = fopen(fullpath, "w");
        if (file != NULL) {
            fclose(file);
        } 
    }

    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore); // Unlocking after atomicity

    return NULL;
}

int main() {
    file_data fd = {"baseName", "directory"};

    sem_init(&semaphore, 0, 1);
    pthread_t thread1, thread2;

    pthread_create(&thread1, NULL, check_and_create, &fd);
    pthread_create(&thread2, NULL, check_and_create, &fd);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    sem_destroy(&semaphore);
}
```

This is a basic example of a C library that checks if a file exists, renames it (if needed), and creates it if it does not exist. It uses locks for mutual exclusion and atomicity during the operation with `pthread_mutex_t` and `semaphore`. 

