    if (extendedList == NULL) {
        releaseLock(lockId);
        logMessage("Failed to allocate memory. Skipping operation.");
        return NULL;
    }

    /* Copy the current state list */
    for (int i = 0; i < numCurrentStates; ++i){
        extendedList[i] = currentStates[i];
    }

    /* Extend the list with new states from the FSA */
    extendedList[numCurrentStates] = fsa->transitions[lastIndex];

    releaseLock(lockId);
    logMessage("Lock released successfully.");

    return extendedList;
}
```

Remember this code is only a blueprint and should be adjusted based on your actual needs, system constraints, FSA structure, error handling strategy and distributed lock management.
']

