        int outlen, tmplen;
        unsigned char outbuf[plaintext.size()*2+16]; // Ensure enough space for ciphertext
        EVP_EncryptUpdate(ctx, outbuf, &outlen, (unsigned char*)plaintext.c_str(), plaintext.size());
        std::string ret = std::string((char*)outbuf, outlen);
        return ret;
    }
    std::string decrypt(const std::string& ciphertext) override {
        int outlen, tmplen;
        unsigned char outbuf[ciphertext.size()]; // Ensure enough space for plaintext
        EVP_DecryptUpdate(ctx, outbuf, &outlen, (unsigned char*)ciphertext.c_str(), ciphertext.size());
