void* manageDependenciesAndUpdate(int** currentStates, int numStates, FSAStruct* fsa, int lastIndex) {
    pthread_t thread;
    sem_t semaphore;

    // Initialize semaphore before using it
    if (sem_init(&semaphore, 0, 1) != 0) {
        return NULL;
    }

    int** args = malloc(sizeof(*args)*3);
    if (!args) {
        return NULL;
    }

    *args = &numStates;
    *(args + 1) = fsa;
    *(args + 2) = &lastIndex;

    // Create a new thread to handle dependency resolution and state update
    if (pthread_create(&thread, NULL, updateStateList, args)) {
        return NULL;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Logic for resolving dependencies goes here
    // ...

    sem_destroy(&semaphore);
    free(args);
}
