Implementation:

```c
#include <stdio.h>
#include <assert.h>
#define INITIAL_SIZE (256)
typedef struct bucket {
    int64_t value;
    bool used;
} Bucket;
struct hashset {
    pthread_mutex_t mutex;
    size_t tableSize, count;
    Bucket* buckets;
};

HashSet* create_hashset(size_t initialSize) {
    HashSet *tmp = (HashSet*)malloc(sizeof(HashSet));
    if (pthread_mutex_init(&tmp->mutex, NULL) != 0) {
        free(tmp);
        return NULL; 
    }
    tmp->tableSize = initialSize > 0 ? initialSize : INITIAL_SIZE;
    tmp->count = 0;
    tmp->buckets = (Bucket*)calloc(sizeof(Bucket), tmp->tableSize);
    assert(tmp->buckets != NULL);
    return tmp;
}
void destroy_hashset(HashSet* set) {
    free(set->buckets);
    pthread_mutex_destroy(&set->mutex);
    free(set);
}
bool insert_unique(HashSet* set, int64_t value) {
    size_t hash = (size_t)value; // Simple hash function for demonstration purposes
    pthread_mutex_lock(&set->mutex);
    Bucket *b = &set->buckets[hash % set->tableSize];

    if (!b->used || b->value != value) { // Duplicate check
        b->value = value;
        b->used = true;
        set->count++;
        pthread_mutex_unlock(&set->mutex);
        return true; 
    }
    pthread_mutex_unlock(&set->mutex);
    return false; // Duplicate found, insert failed.
}
```
