// A simple linked list that holds the array
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;  // Start of list (linked list)
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Add function (adds to the end of linked list)
void add(NFAPI_CRC_INDICATION_PDU_T data){
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);  // Protect shared resources

    if (head == NULL){
        head = newNode;
    } else {
        Node* temp = head;
        while(temp->next != NULL){
            temp = temp->next;
        }
        temp->next = newNode;
    }

    pthread_mutex_unlock(&lock);  // Unprotect shared resources
}

// Remove function (removes from the end of linked list)
void remove(){
    if(head == NULL){
        return;
    }

    pthread_mutex_lock(&lock);  // Protect shared resources

    Node* temp = head;
    Node* prev = NULL;

    while(temp->next != NULL){
        prev = temp;
        temp = temp->next;
    }

    if(prev == NULL){  // If only one element in list
        free(head);
        head = NULL;
    } else {
        prev->next = NULL;
        free(temp);
    }

    pthread_mutex_unlock(&lock);  // Unprotect shared resources
}
```

