let mut rx = vec![Token(0)];
let shared_socket = Arc::new(socket);
let codec = UdpCodec::new(Box::new(move |msg| {
    // Process incoming message here
}), Box::new(|err, _| {
    // Handle error here
}));

let mut events = Events::with_capacity(1024);
loop {
    let timeout = if events.backend().ready(&rx).is_empty() {
        None
    } else {
        Some(Duration::from_millis(10))
    };

    events.receive(timeout)?;

    for event in &events {
        let socket = match Arc::get_mut(&shared_socket) {
            Some(socket) => socket,
            _ => continue
        };

        codec.decode_buf_into(&mut rx, &mut BytesMut::with_capacity(1500), socket)?;
    }
}
