```c
#include <stdlib.h>
#include <stdatomic.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// This is just a placeholder for your structure definition
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    _Atomic(int) CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    atomic_size_t size;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    atomic_init(&arr->size, 0);
    pthread_mutex_init(&arr->lock, NULL);

    srand(time(NULL)); // Initialize random seed
    return arr;
}

void destroy_dynamic_array(DynamicArray *arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

int add_element(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    size_t currentSize;

    // Atomic fetch and increment
    currentSize = atomic_fetch_add(&arr->size, 1);

    if (currentSize >= arr->capacity) {
        pthread_mutex_lock(&arr->lock);
        size_t oldCapacity = arr->capacity;

        // Double capacity each time we need to grow the array
        arr->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* newData = realloc(arr->data, arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!newData) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Failed to allocate memory
        }

        arr->data = newData;
        memset(arr->data + oldCapacity, 0, (arr->capacity - oldCapacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&arr->lock);
    }

    arr->data[currentSize] = element;
    // Randomly set CRCFLAG between 0 and 1
    atomic_store(&arr->data[currentSize].CRCFLAG, rand() % 2);
    return currentSize;
}
```

