async function loadScript(script) {
  // validate script object
  if (!script || !script.id || !script.src || !script.type) {
    throw new Error('Invalid script: missing id, src or type');
  }

  // check if script is in cache
  const cachedScript = loadFromCache(script);
  if (cachedScript) return Promise.resolve();

  // fetch metadata and validate again
  let externalMetadata;
  try {
    externalMetadata = await fetchExternalApi(script.src);
  } catch (error) {
    console.error('Failed to fetch metadata:', error);
    throw new Error('Invalid script: failed to fetch metadata');
  }

  if (externalMetadata && externalMetadata.id !== script.id) {
    throw new Error('Invalid script: id mismatch with metadata');
  }

  // dynamically create script tag and append it to the body
  const newScript = document.createElement('script');
  newScript.id = script.id;
  newScript.src = script.src;
  newScript.type = script.type;
  newScript.charset = script.charset || 'UTF-8';

  document.body.appendChild(newScript);
}

function loadFromCache(script) {
