const express = require('express');
const { check, validationResult } = require('express-validator');
const mongoose = require('mongoose');

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/employees', { useNewUrlParser: true });

// Create a schema for employees
const EmployeeSchema = new mongoose.Schema({
  name: String,
  age: Number,
  position: String,
});

// Create a model based on the schema
const Employee = mongoose.model('Employee', EmployeeSchema);

const app = express();
app.use(express.json());

// An example of middleware to validate incoming data
app.post('/employees', [
  check('name').isLength({ min: 1 }),
  check('age').isNumeric(),
  check('position').isLength({ min: 1 }),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(422).json({ errors: errors.array() });
  }

  const employee = new Employee({
    name: req.body.name,
    age: req.body.age,
    position: req.body.position,
  });

  // Save the new employee to MongoDB
  employee.save((error) => {
    if (error) res.status(500).send(error);

    res.status(201).json({
      message: 'Employee created successfully',
    });
  });
});

app.listen(3000, () => console.log('App listening on port 3000'));
