import java.util.*;

public class Orchestrator {
    private Map<String, Service> services = new HashMap<>();

    public void registerService(String name, Service service) {
        this.services.put(name, service);
    }

    public void unregisterService(String name) {
        this.services.remove(name);
    }

    public Service getService(String name) {
        return services.get(name);
    }

    // Load balancing can be a simple round-robin strategy, where requests are distributed evenly to all available services
    public void loadBalance() {
        List<Service> healthyServices = getHealthyServices();

        if (healthyServices.isEmpty()) return;

        int current = 0;

        while (!requestQueue.isEmpty()) {
            Service service = healthyServices.get(current % healthyServices.size());
            Request request = requestQueue.poll();

            service.processRequest(request);

            current++;
        }
    }

    // Get only services that are currently healthy and ready to process requests
    private List<Service> getHealthyServices() {
        List<Service> healthyServices = new ArrayList<>();

        for (Service service : this.services.values()) {
            if (service.isHealthy()) healthyServices.add(service);
        }

        return healthyServices;
    }
}
``` 

