<?php
class ClinicStatusManager {
    private $db;
    private $api;
    private $logger;
    private $monitoringSystem;

    public function __construct(DatabaseConnectionInterface $db, ThirdPartyAPIInterface $api, LoggerInterface $logger, MonitoringSystemInterface $monitoringSystem) {
        $this->db = $db;
        $this->api = $api;
        $this->logger = $logger;
        $this->monitoringSystem = $monitoringSystem;
    }

    public function updateClinicStatus($clinicId, $status, $ip) {
        try {
            $this->validateInputs([$clinicId, $status, $ip]);

            // Check if clinic exists in database and user has necessary permissions
            $this->api->authenticateAndAuthorize();

            // Start a transaction to ensure data consistency
            $this->db->beginTransaction();

            // Update clinic status, last modified IP address, and last modified date
            $data = [
                'status' => $status, 
                'last_modified_ip' => $ip, 
                'last_modified_date' => date('Y-m-d H:i:s')
            ];
            $this->db->updateClinic($clinicId, $data);

            // Commit the transaction once successful
            $this->db->commit();
        } catch (Exception $e) {
            if ($this->db->inTransaction()) {
                $this->db->rollBack();
            }
            $this->logger->error($e->getMessage());
            $this->monitoringSystem->sendAlert('Clinic status update failed');
        } finally {
            $this->api->logout();
        }
    }

    private function validateInputs(array $inputs) {
        foreach ($inputs as $input) {
            if (!isset($input)) {
                throw new InvalidArgumentException('Missing input parameters');
            }
        }
    }
}
?>
