Part 2: The Session Management System 
```C#
public class SessionManagementService : ISessionManagementService {
    private readonly IDistributedCache _cache;

    public SessionManagementService(IDistributedCache cache) {
        _cache = cache;
    }

    public void StoreSessionTokenForUserId(string userId, string token){
        _cache.SetStringAsync(userId, token);
    }

    public bool VerifyAndRevokeSessionToken(string userId, string token) {
        var storedToken = _cache.GetStringAsync(userId).Result;

        if (storedToken != null && storedToken == token){
            _cache.Remove(userId);
            return true;
        }

        return false;
    }
}
```
