['This is a large task that would require an entire project worth of work to properly implement from start to finish due to its complexity. However, I will give you a simplified version of how you might implement the main components like `PasswordUpdater` and `BackgroundExecutor`. 

```php
class PasswordUpdater {
    private $db;

    public function __construct(PDO $db) {
        $this->db = $db;
    }

    public function updatePassword($userId, $newPassword): bool {
        if (!$this->isValidPassword($newPassword)) {
            throw new Exception('Invalid password');
        }

        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

        $stmt = $this->db->prepare("UPDATE users SET password=? WHERE id=?");
        if (!$stmt->execute([$hashedPassword, $userId])) {
            throw new Exception('Failed to update the password');
        }

        return true;
    }

    private function isValidPassword($password): bool {
        $uppercase = preg_match('@[A-Z]@', $password);
        $lowercase = preg_match('@[a-z]@', $password);
        $number    = preg_match('@[0-9]@', $password);
        $specialChars = preg_match('@[^\w]@', $password);

        return !(strlen($password) < 12 || !$uppercase || !$lowercase  || !$number || !$specialChars );
    }
}

class BackgroundExecutor {
    private $queue;

    public function __construct(QueueInterface $queue) {
        $this->queue = $queue;
    }

    public function executeInBackground(callable $task): void {
        $this->queue->push([$task]);
    }
}
``` 
