#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

// Dummy geospatial data service
class GeospatialDataService {
public:
    void asyncUpdate(std::string key, std::string value) { /* Implementation here */ }
};

template<typename K, typename V>
class SpatialHashMap {
private:
    struct Bucket {
        std::unordered_map<K,V> map;
        mutable std::mutex mtx;
    };
    GeospatialDataService gds_;
    size_t capacity_;
    std::vector<Bucket> buckets_;
public:
    SpatialHashMap(size_t capacity = 1024) : capacity_(capacity), buckets_(capacity) {}

    V get(const K& key) const {
        size_t idx = std::hash<K>{}(key) % capacity_;
        std::lock_guard<std::mutex> lck(buckets_[idx].mtx);
        auto itr = buckets_[idx].map.find(key);
        if (itr != buckets_[idx].map.end()) {
            return itr->second; 
        } else {
            throw std::out_of_range("Key not found");
        }
    }

    void set(const K& key, const V& value) {
        size_t idx = std::hash<K>{}(key) % capacity_;
        std::lock_guard<std::mutex> lck(buckets_[idx].mtx);
        buckets_[idx].map.insert({key, value});
        gds_.asyncUpdate(key, value);  // Asynchronous update
    }

    void erase(const K& key) {
        size_t idx = std::hash<K>{}(key) % capacity_;
        std::lock_guard<std::mutex> lck(buckets_[idx].mtx);
        buckets_[idx].map.erase(key);
    }
};
```
