    public async Task<List<WebsiteStatus>> DeploySitesAsync(IEnumerable<WebsiteConfig> websiteConfigs)
    {
        var statuses = new List<WebsiteStatus>();

        foreach (var config in websiteConfigs)
        {
            _logger.LogInformation("Starting deployment for site: " + config.SiteName);

            var serverUri = $"{config.Protocol}://{config.ServerIP}:{config.Port}/{config.DirectoryPath}/";
            var webConfigPath = Path.Combine(config.DirectoryPath, "web.config");

            try
            {
                // Validate configuration: Directory exists and contains a valid web.config file.
                if (!Directory.Exists(config.DirectoryPath) || !File.Exists(webConfigPath))
                    throw new Exception("Invalid directory or missing web.config file.");

                // Retrieve OAuth token from secure storage, then validate it. 
                var oauthToken = await GetOAuthTokenAsync();
                if (!IsValidToken(oauthToken))
                    throw new Exception("Invalid OAuth token.");

                // Make asynchronous HTTP request to server using the provided token and URI.
                var response = await _httpClient.PostAsync(serverUri, new StringContent(JsonConvert.SerializeObject(config), 
                    System.Text.Encoding.UTF8, "application/json"));

                // Log any response details or potential errors.
                if (response.IsSuccessStatusCode)
                {
                    _logger.LogInformation("Deployment successful for site: " + config.SiteName);
                    statuses.Add(new WebsiteStatus{ Success = true, Details = $"Deployed site '{config.SiteName}'." });
                }
                else 
                {
                    var errorDetails = await response.Content.ReadAsStringAsync();
                    _logger.LogError("Deployment failed for site: " + config.SiteName + 
