import google.cloud.logging as cloud_logging  # Google Cloud Logging SDK

@dataclass
class LogRecord:
    timestamp: float
    data: Dict[str, Any]

class LogService(Protocol):
    async def log(self, record: LogRecord) -> None: ...

class AWSServiceLogging:
    def __init__(self, service_name):
        self.client = boto3.client('logs')  # assuming AWS SDK is already configured
        self.service_name = service_name

    async def log(self, record: LogRecord) -> None:
        response = self.client.put_log_events(
            logGroupName=self.service_name,
            logStreamName='string',
            logEvents=[
                {
                    'timestamp': int(record.timestamp * 1e3),  # convert to ms as per AWS API
                    'message': str(record.data)
                },
            ]
        )

class GoogleServiceLogging:
    def __init__(self, service_name):
        self.client = cloud_logging.Client()
        self.service_name = service_name

    async def log(self, record: LogRecord) -> None:
        logger = self.client.logger(self.service_name)
        logger.log_text(record.data, timestamp=record.timestamp)

class CustomServiceLogging:
    """Implement this as per your custom service"""

class LogManager:
    def __init__(self):
        self.services = {}  # Dict[str, LogService]

    async def log(self, service_name: str, record: LogRecord) -> None:
