['Here's a basic structure of how you can design this microservice:

```csharp
using System;
using System.Security.Cryptography;
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using System.Text;
using Microsoft.Extensions.Logging;
using Microsoft.EntityFrameworkCore;
using Polly;

public class HashingController : ControllerBase
{
    private readonly ILogger<HashingController> _logger;
    private readonly HashingContext _context;

    public HashingController(ILogger<HashingController> logger, HashingContext context)
    {
        _logger = logger;
        _context = context;
    }

    [HttpPost]
    public async Task<ActionResult<string>> Post([FromBody] string data)
    {
        var hash = await HashData(data);

        return Ok(hash);
    }

    private async Task<string> HashData(string input)
    {
        using (MD5 md5Hash = MD5.Create())
        {
            byte[] data = md5Hash.ComputeHash(Encoding.UTF8.GetBytes(input));

            StringBuilder sBuilder = new StringBuilder();

            for (int i = 0; i < data.Length; i++)
            {
                sBuilder.Append(data[i].ToString("x2"));
            }

            var hash = sBuilder.ToString();

            await _context.Hashes.AddAsync(new HashingEntity{Hash = hash});
            await _context.SaveChangesAsync();

            return hash;
        }
    }
}
```

In the above code, we're first creating a `HashingController` that takes in an input string from the user via HTTP POST request and sends it to `HashData` method where MD5 hashing is performed. We also have a logger setup which can be used for logging purposes. 

