    [Route("api/[controller]")]
    public class YourController : ControllerBase
    {
        private readonly HttpClient _client;
        private readonly IConfiguration _configuration;

        public YourController(IHttpClientFactory httpClientFactory, IConfiguration configuration)
        {
            _client = httpClientFactory.CreateClient();
            _configuration = configuration;
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody]YourModel model)
        {
            var apiUrl = _configuration["ExternalApi"]; // Fetch API URL from configuration
            var policy = Policy
                .Handle<Exception>()
                .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

            await policy.ExecuteAsync(async () =>
            {
                var content = new StringContent(JsonConvert.SerializeObject(model), Encoding.UTF8, "application/json");

                using (var response = await _client.PostAsync(apiUrl, content)) // Make the HTTP POST request
                {
                    if (!response.IsSuccessStatusCode)
                        throw new Exception("API call failed.");
                }
            });

            // Continue with data processing and storing in a scalable, remote database...

            return Ok();
        }
    }
}
```
