    public T LoadAndDecrypt<T>(string filePath, byte[] key, byte[] iv, byte[] authTag) where T : class
    {
        try 
        {
            var serializedData = _cloudStorageProvider.DownloadFile(filePath);

            // Check if we have this file in cache first
            if (!_cache.TryGetValue(filePath, out var decryptedData)) 
            {
                // Decrypt the data using AES-GCM and store it to cache
