            return JsonSerializer.Deserialize<T>(decryptedData);
        } 
        catch (Exception ex) when (ex is FileNotFoundException || ex is CryptographicException) 
        {
            _logger.LogError("Error loading and decrypting file: " + filePath, ex);
            throw;
        }
    }

