['Creating such a complex system would be beyond the scope of this response, but here's an example of how you could start structuring your library.

```c
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/stat.h>

typedef struct FileManager {
    pthread_mutex_t mutex;
} FileManager;

FileManager* createFileManager() {
    FileManager* fm = malloc(sizeof(FileManager));
    if (pthread_mutex_init(&fm->mutex, NULL) != 0) {
        printf("\n mutex init has failed\n");
        return NULL;
    }
    return fm;
}

char* generateUniqueFilename(FileManager* fm, const char* base_name, const char* directory) {
    pthread_mutex_lock(&fm->mutex);

    DIR *dir = opendir(directory);
    if (dir == NULL) {
        printf("Cannot open directory '%s'\n", directory);
        return NULL;
    }

    int counter = 0;
    char* filename = malloc(strlen(base_name) + 256);
    sprintf(filename, "%s/%s-%d", directory, base_name, counter);

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue; // skip self and parent directory

        char* path = malloc(strlen(directory) + strlen(ent->d_name) + 2);
        sprintf(path, "%s/%s", directory, ent->d_name);

        struct stat st;
        if (stat(path, &st) == -1) continue; // file does not exist

        if (S_ISREG(st.st_mode)) {
            if (strcmp(filename, ent->d_name) == 0) {
                counter++;
                sprintf(filename, "%s/%s-%d", directory, base_name, counter);
                break;
            }
        }

        free(path);
    }

    closedir(dir);

    pthread_mutex_unlock(&fm->mutex);

    return filename;
}
```

This is a simplified version and does not include all the requirements you've outlined. For example, it doesn't deal with potential naming conflicts when creating files across multiple machines in a distributed environment. You would need to incorporate additional logic for this, possibly involving some form of distributed consensus algorithm like Raft or Paxos.
