@RestController
@RequestMapping("/api/resource")
public class ResourceController {

    private PriorityQueue<Service> services = new PriorityQueue<>(); // Assume Service is an interface with methods getPriority(), updateResource(id, data), etc.

    public ResourceController() {
        // Initialize and add services to the queue in order of priority. 
        // The service with the highest priority (0) should be at the front of the queue.
        // This is a simplified example and may need to be adjusted based on actual implementation
        services.add(new ServiceX()); 
        services.add(new ServiceY());
        services.add(new ServiceZ());
        services.add(new ServiceW());
    }

    @PutMapping("/{id}")
    public ResponseEntity<String> updateResource(@PathVariable("id") String id, @RequestBody Resource data) {
        for (Service service : services) { // Start with highest priority service
            try { 
                service.updateResource(id, data); // Try updating resource with each service
                return ResponseEntity.ok().body("Resource updated successfully");
            } catch (Exception e) {
                // Log error and continue to next service
                System.out.println("Failed to update resource with " + service.getClass().getName() + ". Error: " + e.getMessage());
            }
        }
        return ResponseEntity.internalServerError().body("Failed to update resource"); 
    }
}
