            mongocxx::client conn{uri};
            auto db = conn["test"]; // Replace 'test' with your database name

            try {
                return db[collection].find_one(std::move(filter));
            } catch (const mongocxx::query_exception& e) {
                std::cout << "Get failed: " << e.what() << "\n";
                return {}; // Return empty optional if get fails
            }
        }
