import time

class WebApp:
    def __init__(self):
        self.app = Quart(__name__)
        self.socketio = SocketIO(self.app)
        self.clients = {}
        self.oauth_providers = []  # Add OAuth2 providers here.

        @self.socketio.on('connect')
        def connect():
            self.clients[request.sid] = {'session': None}

        @self.app.route('/login/<provider>', methods=['GET'])
        async def login(provider):
            if provider not in self.oauth_providers:
                return {"error": "Unknown OAuth2 provider."}, 400

            client = BackendApplicationClient(client_id=self.oauth_providers[provider]['client_id'])
            oauth = OAuth2Session(client=client)
            authorization_url, state = oauth.authorization_url(self.oauth_providers[provider]['authorize_url'])

            self.clients[request.sid]['session'] = oauth
            return redirect(authorization_url)

        @self.app.route('/callback/<provider>', methods=['GET'])
        async def callback(provider):
            if provider not in self.oauth_providers or self.clients[request.sid]['session'] is None:
                return {"error": "Unknown OAuth2 provider."}, 400

            token = self.clients[request.sid]['session'].fetch_token(self.oauth_providers[provider]['token_url'], client_secret=self.oauth_providers[provider]['client_secret'], authorization_response=request.url)

            return redirect('/')

        @self.socketio.on('message')
        async def handle_message(data):
            await self.socketio.emit('message', data, room='all')
