```c
/* common.h */
#ifndef COMMON_H
#define COMMON_H

typedef struct {
    int id;
} Item;

typedef struct Node {
    Item item;
    struct Node* next;
} Node;

Node* createNode(Item item);
void insertNode(Node** head, Item item);
void deleteNode(Node** head, int id);
void printList(Node* node);

#endif /* COMMON_H */
```

```c
/* common.c */
#include <stdio.h>
#include <stdlib.h>
#include "common.h"

Node* createNode(Item item) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        return NULL;
    }

    newNode->item = item;
    newNode->next = NULL;
    return newNode;
}

void insertNode(Node** head, Item item) {
    Node* newNode = createNode(item);
    if (!newNode) {
        printf("Error creating a new node.\n");
        return;
    }

    newNode->next = *head;
    *head = newNode;
}

void deleteNode(Node** head, int id) {
    Node *temp = *head, *prev;

    if (temp != NULL && temp->item.id == id) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->item.id != id) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;
    free(temp); 
}

void printList(Node* node) {
    while (node != NULL) {
        printf(" %d ", node->item.id);
        node = node->next;
    }
}
```
The code above is a simple linked list implementation where `Item` is a structure holding an integer `id`, `Node` is the structure for each item in the list, and functions to insert and delete nodes. Note that this example doesn't include any error checking or robustness features you would need in a real-world scenario.
']

