['Here is a simplified example in C++ based on your requirements using boost::asio for networking and threading, and boost::interprocess for shared memory management. Please note that this code is highly abstracted and should be used as a starting point or reference rather than production ready software. It also does not include all the advanced features you have mentioned in your requirements (such as external messaging service API integration) which would require significantly more complex and custom implementation.

```cpp
#include <boost/asio.hpp>
#include <boost/interprocess/managed_shared_memory.hpp>
#include <iostream>
#include <thread>

namespace bip = boost::interprocess;
using namespace std;

class MessageQueue {
public:
    MessageQueue(size_t max_messages) : m_max_messages(max_messages) {}
    ~MessageQueue() { destroy(); }

    void push(const string& message);
    bool pop(string* message, size_t timeout = 0);

private:
    bip::managed_shared_memory m_segment;
    bip::message_queue* m_mq = nullptr;
    const size_t m_max_messages;

    void create();
    void destroy();
};

void MessageQueue::create() {
    bip::shared_memory_object::remove("MySharedMemory");
    m_segment = bip::managed_shared_memory(bip::open_or_create, "MySharedMemory", 65535);
    m_mq = m_segment.construct<bip::message_queue>("MyMessageQueue")(m_max_messages);
}

void MessageQueue::destroy() {
    bip::shared_memory_object::remove("MySharedMemory");
}

void MessageQueue::push(const string& message) {
    if (!m_mq) create();

    m_mq->send(message.c_str(), message.size(), 0);
}

bool MessageQueue::pop(string* message, size_t timeout = 0) {
    if (!m_mq) return false;

    boost::posix_time::ptime abs_time = boost::get_system_time() + boost::posix_time::seconds(timeout);
    bip::message_queue::size_type recvd_size;
    unsigned int priority;

    if (m_mq->timed_receive(&recvd_size, sizeof(recvd_size), priority, abs_time)) {
        vector<char> buffer(recvd_size);
        m_mq->receive(&buffer.front(), recvd_size, priority);
        *message = string(&buffer.front(), &buffer.back() + 1);
        return true;
    } else {
        return false;
    }
}
```
This is a very basic and simplified example just to illustrate the overall structure of a message queue system in C++ using boost libraries. You would need to develop this further based on your requirements, considering many more factors including robust error handling, network integration, performance optimization etc. The actual implementation can be highly complex depending upon the specifics of your application.
']

