                    return true;
                } else {
                    $this->log->error('Invalid metrics response', ['id' => $id, 'response' => $response]);
                    throw new Exception('Invalid metrics data');
                }
            } else {
                $this->log->info('Using cached data for id: '.$id);
                return true; // Use cache data instead of updating.
            }
        } catch (Exception $e) {
