}

class Logger {
    public function info($message, array $context = []) { /* ... */ }
    public function error($message, array $context = []) { /* ... */ }
}

class UnreliableAPI {
    private function makeRequest($data) { /* ... */ }

    public function callApiWithRetries($metrics, $retries, $delayInMilliseconds) {
        $attempt = 0;
        while ($attempt < $retries) {
            try {
                return $this->makeRequest($metrics);
            } catch (Exception $e) {
                $attempt++;
                if ($attempt === $retries) {
                    throw new Exception('Failed to call API after '.$retries.' attempts');
                }
                usleep($delayInMilliseconds * 1000); // Delay in microseconds.
            }
        }
    }
