// Using Spring's WebClient for REST calls and Jackson for JSON parsing
import org.springframework.web.reactive.function.client.*;
import com.fasterxml.jackson.databind.ObjectMapper;

@RestController
public class TransactionFilterService {
    // Use a concurrent hash map to store the current highest weightedSum and transactionId for each category
    private ConcurrentHashMap<String, AtomicReference<Pair>> transactionMetrics = new ConcurrentHashMap<>(); 

    // Use WebClient for REST calls
    private final WebClient webClient;
    private ObjectMapper objectMapper = new ObjectMapper();

    public TransactionFilterService(WebClient.Builder builder) {
        this.webClient = builder.baseUrl("http://external-service").build();
    }

    // Endpoint for filtering and processing transactions
    @PostMapping("/transactions")
    Mono<String> processTransaction(@RequestBody String transactionJson) throws Exception {
        Transaction transaction = objectMapper.readValue(transactionJson, Transaction.class);

        if (isValid(transaction)) {
            return callExternalServiceAndUpdateMetrics(transaction);
        } else {
            // Handle invalid transactions according to your requirements
            return Mono.just("Invalid transaction");
        }
    }

    private boolean isValid(Transaction transaction) {
        // Add necessary checks here, e.g., age should be less than 30
        return true;
    }

    private Mono<String> callExternalServiceAndUpdateMetrics(Transaction transaction) {
        return webClient.post()
                .uri("/transactions")
                .bodyValue(transactionJson)
                .retrieve()
                .onStatus(HttpStatus::is5xxServerError, response -> 
                        Mono.error(new ServerException("Server error"))
                    )
                .onStatus(HttpStatus::is4xxClientError, response -> 
                        Mono.error(new ClientException("Client error"))
                    )
                .bodyToMono(String.class)
                .doOnSuccessOrError((responseBody, throwable) -> {
                    // Update transactionMetrics if the request was successful
                    if (throwable == null) {
                        updateTransactionMetrics(transaction);
                    }
                });
    }

    private void updateTransactionMetrics(Transaction transaction) {
        String category = transaction.getCategory();
        Pair currentMaxPair = transactionMetrics.computeIfAbsent(category, k -> new AtomicReference<>(new Pair(0, "")));

        // Use compareAndSet to ensure atomicity of updates
        while (true) {
            Pair observedPair = currentMaxPair.get();

            if (transaction.getWeightedSum() > observedPair.getWeightedSum()) {
                Pair newPair = new Pair(transaction.getWeightedSum(), transaction.getTransactionId());

                if (currentMaxPair.compareAndSet(observedPair, newPair)) {
                    break; // Exit the loop once we successfully updated the max pair
                }
            } else {
                break;
            }
        }
    }

    @GetMapping("/metrics")
    Map<String, Pair> getMetrics() {
        return transactionMetrics.entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    }
}
```
