```cpp
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>

class UserActivity {
public:
    void ingestLog(const std::string& user, int activity) {
        // Acquire the lock to ensure thread safety.
        std::lock_guard<std::mutex> guard(m);

        auto it = userActivities.find(user);
        if (it == userActivities.end()) {
            userActivities[user] = activity;
        } else {
            // Update the total activity for this user and increment the count of logs received.
            userActivities[user].first += activity;
            userActivities[user].second += 1;
        }

        // Notify any waiting threads that a new log has been added.
        cv.notify_all();
    }

    double getAverageActivity(const std::string& user) {
        std::lock_guard<std::mutex> guard(m);

        // Wait until there's something to process.
        while (userActivities[user].second == 0) {
            cv.wait(guard);
        }

        return static_cast<double>(userActivities[user].first) / userActivities[user].second;
    }

private:
    // Maps users to pairs of (total activity, count).
    std::unordered_map<std::string, std::pair<int, int>> userActivities;

    // Mutex and condition variable for thread safety.
    std::mutex m;
    std::condition_variable cv;
};
```

This C++ class represents a simplified model of a user activity logger. The `ingestLog` function adds new log entries, while the `getAverageActivity` function computes and returns the average daily activity level for a given user. A mutex is used to ensure that access to the `userActivities` map is synchronized across threads. 

This example also uses condition variables to notify waiting threads when new logs are added, allowing them to start processing data sooner than they might otherwise do. This can help reduce latency under heavy load and improve overall system efficiency.
