    issuerBaseURL: `https://YOUR_DOMAIN.us.auth0.com/`,
});

app.get('/executeCommand', checkJwt, (req, res) => {
    const command = req.query.command;
    // Validate the command against a whitelist
    if (!isWhitelisted(command)) return res.status(403).send("Forbidden: Command not allowed");

    // Execute the system-level shell command using 'child_process' module
    const { exec } = require('child_process');
    const process = exec(command, (error, stdout, stderr) => {
        if (error) return res.status(500).send(`Error: ${error}`);

        // Log the command execution
        logCommandExecution(req.auth.payload, command, stdout, stderr);
    });
});

app.listen(3000, () => console.log('Server is running'));
