    pthread_rwlock_t lock;   // Reader-writer lock to ensure thread safety
    int count;  // Number of items in the cache
} Cache;

// Initialize cache
void initCache(Cache* cache) {
    assert(pthread_rwlock_init(&cache->lock, NULL) == 0);
    for (int i = 0; i < 100; ++i) 
        cache->sibs[i] = NULL;
}

// Destroy cache
void destroyCache(Cache* cache) {
    assert(pthread_rwlock_destroy(&cache->lock) == 0);
    for (int i = 0; i < 100; ++i) 
        if (cache->sibs[i] != NULL) free(cache->sibs[i]);
}

// Add SIB to cache
void addToCache(Cache* cache, Sib* sib) {
    assert(pthread_rwlock_wrlock(&cache->lock) == 0);  // Acquire write lock

    if (cache->count < 100) {
        cache->sibs[cache->count++] = sib;
    } else {
        // Implement LRU eviction strategy here, i.e., replace the oldest SIB with new one
    }

    assert(pthread_rwlock_unlock(&cache->lock) == 0);  // Release write lock
}

// Fetch SIB from cache
Sib* getFromCache(Cache* cache, int version) {
    assert(pthread_rwlock_rdlock(&cache->lock) == 0);  // Acquire read lock

    for (int i = 0; i < cache->count; ++i) {
        if (cache->sibs[i]->version == version) {
            assert(pthread_rwlock_unlock(&cache->lock) == 0);  // Release read lock before returning
            return cache->sibs[i];
        }
    }

    assert(pthread_rwlock_unlock(&cache->lock) == 0);  // Release read lock before returning
    return NULL;  // If SIB not found in cache, return null
}

// Function to handle updates in a thread-safe manner
void updateSIBConcurrently(Cache* cache, Sib* sib) {
    assert(pthread_rwlock_wrlock(&cache->lock) == 0);  // Acquire write lock

    for (int i = 0; i < cache->count; ++i) {
        if (cache->sibs[i]->version == sib->version) {
            // Replace old SIB with new one
            free(cache->sibs[i]);  // Free the memory occupied by old SIB
            cache->sibs[i] = sib;
        }
    }

    assert(pthread_rwlock_unlock(&cache->lock) == 0);  // Release write lock
}
