// Struct to hold filename generation info
typedef struct {
    pthread_mutex_t mutex;
    char *prefix;
    long counter;
} FileNameGenerator;

void fileNameGenInit(FileNameGenerator* gen, const char* prefix) {
    pthread_mutex_init(&gen->mutex, NULL);
    gen->prefix = strdup(prefix);
    gen->counter = 0;
}

// Thread-safe unique filename generation
char* getUniqueFileName(FileNameGenerator* gen) {
    pthread_mutex_lock(&gen->mutex);
    ++gen->counter;
    char *filename = malloc(snprintf(NULL, 0, "%s%ld", gen->prefix, gen->counter) + 1);
    sprintf(filename, "%s%ld", gen->prefix, gen->counter);
    pthread_mutex_unlock(&gen->mutex);
    return filename;
}

// Thread-safe file existence check
bool doesFileExist(char* filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_EXCL, 0644);
    if (fd < 0) return true; // File already exists

    close(fd);
    unlink(filename); // Clean up the created file
    return false;
}

// Thread-safe rename operation
bool renameFile(char* oldName, char* newName) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Lock to prevent naming collision
    pthread_mutex_lock(&mutex); 

    if (doesFileExist(newName)) {
        pthread_mutex_unlock(&mutex);
        return false;
    }

    rename(oldName, newName);

    pthread_mutex_unlock(&mutex); // Unlock after operation
    return true;
}
```
