    void addMessage(const LTE_MME_MESSAGE_T &msg){
        std::lock_guard<std::mutex> lock(mtx);
        if(msg.isValid()){
            messages.push_front(msg); // assuming insertion at front for performance reason
        }else{
            throw std::invalid_argument("Invalid Message");
        }
    }

    boost::optional<LTE_MME_MESSAGE_T> removeMessage(){
        std::lock_guard<std::mutex> lock(mtx);
        if(!messages.empty()){
            auto removedMsg = messages.front(); // assuming removal from front for performance reason
            messages.pop_front();
            return boost::optional<LTE_MME_MESSAGE_T>(removedMsg);
        }else{
            return boost::none;
        }
    }

    void insertAfterFirstOccurrence(const std::string& str1, const std::string& str2){
        std::lock_guard<std::mutex> lock(mtx);
        auto it = find_if(messages.begin(), messages.end(), [str1](LTE_MME_MESSAGE_T msg) {return msg.NASHeader == str1;});
        if (it != messages.end()) {
            LTE_MME_MESSAGE_T newMsg = *it;
            newMsg.NASHeader = str2; 
