```
Now, let's create a basic circular buffer:

```cpp
#include <vector>

class CircularBuffer {
public:
    CircularBuffer(size_t capacity) : data_(capacity), head_(0), tail_(0), size_(0) {}

    void add(HTTP_REQUEST_T request) {
        if (size_ == data_.size()) {
            throw std::runtime_error("Circular buffer is full");
        }

        data_[tail_] = request;
        tail_ = (tail_ + 1) % data_.capacity();
        ++size_;
    }

    HTTP_REQUEST_T remove() {
        if (size_ == 0) {
            throw std::runtime_error("Circular buffer is empty");
        }

        auto request = data_[head_];
        head_ = (head_ + 1) % data_.capacity();
        --size_;
        return request;
    }

private:
    std::vector<HTTP_REQUEST_T> data_;
    size_t head_;
    size_t tail_;
    size_t size_;
};
```
Next, let's implement the logic for adding, removing and retrieving requests from CircularBuffer in a thread-safe manner. For this, you can use std::mutex or other synchronization mechanisms available in C++:

