void add_message(MessageArray* array, LTE_MME_MESSAGE_T* message) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        // increase the capacity of the messages array when full
        array->messages = realloc(array->messages, sizeof(LTE_MME_MESSAGE_T*) * array->capacity * 2);
        array->capacity *= 2;
    }

    array->messages[array->size++] = message;

    pthread_mutex_unlock(&array->lock);
}

LTE_MME_MESSAGE_T* get_message(MessageArray* array, int index) {
    LTE_MME_MESSAGE_T* result;
    pthread_mutex_lock(&array->lock);

    if (index < array->size) {
        result = array->messages[index];
    } else {
        // handle index out of bounds error
        result = NULL;
    }

    pthread_mutex_unlock(&array->lock);
    return result;
}

void remove_message(MessageArray* array, int index) {
    pthread_mutex_lock(&array->lock);

    if (index < array->size) {
        // shift all messages after the removed one forward by 1
        for (int i = index; i < array->size - 1; ++i) {
            array->messages[i] = array->messages[i + 1];
        }
        --array->size;
    } else {
        // handle index out of bounds error
    }

    pthread_mutex_unlock(&array->lock);
}
