// sensorDataStreamLibrary.js
const { EventEmitter } = require('events');
const axios = require('axios'); // third-party library for HTTP requests

class SensorDataStream extends EventEmitter {
    constructor(storageServiceUrl) {
        super();
        this.dataSchema = {};
        this.workers = 1;
        this.pollingInterval = 5000; // default polling interval in ms
        this.externalStorageServiceUrl = storageServiceUrl;
        this.clientConnections = new Map();
    }

    // Add data to the schema
    addData(id, data) {
        if (!this.dataSchema[id]) this.dataSchema[id] = [];
        this.dataSchema[id].push(data);

        // Backup data to external storage service
        axios.post(`${this.externalStorageServiceUrl}/backup`, { id, data })
            .then(() => this.emit('successfulBackup', id))
            .catch((err) => console.error(err));
    }

    // Retrieve data from the schema
    getData(id) {
        return this.dataSchema[id];
    }

    // Add a client connection and emit an event when they disconnect
    addClientConnection(clientId, socket) {
        this.clientConnections.set(clientId, socket);

        socket.on('disconnect', () => {
            this.emit('clientDisconnected', clientId);
            this.clientConnections.delete(clientId);
        });
    }

    // Update the number of workers based on current load
    updateWorkers(newCount) {
        if (newCount > 0 && newCount <= os.cpus().length) this.workers = newCount;
    }

    // Adjust polling interval based on network conditions and client demand
