```c
// File: dynamic_collection.c
#include "dynamic_collection.h"
#include <stdlib.h>

static const size_t INITIAL_CAPACITY = 10;

void init(DynamicCollection *coll) {
    coll->items = malloc(sizeof(CollectionItem) * INITIAL_CAPACITY);
    coll->length = 0;
    coll->capacity = INITIAL_CAPACITY;
}

static void resize(DynamicCollection *coll, size_t newCapacity) {
    CollectionItem *newItems = realloc(coll->items, sizeof(CollectionItem) * newCapacity);
    if (newItems != NULL) {
        coll->items = newItems;
        coll->capacity = newCapacity;
    }
}

void insert(DynamicCollection *coll, CollectionItem item) {
    if (coll->length == coll->capacity) {
        resize(coll, 2 * coll->capacity);
    }
    coll->items[coll->length++] = item;
}

CollectionItem get(DynamicCollection *coll, int index) {
    if (index < coll->length && index >= 0) {
        return coll->items[index];
    } else {
        // Handle out of bounds error
    }
}

size_t size(DynamicCollection *coll) {
    return coll->length;
}

void destroy(DynamicCollection *coll) {
    free(coll->items);
    coll->items = NULL;
    coll->capacity = 0;
    coll->length = 0;
}
```

