    std::string _severity;
    std::string _message;
};

// A logging worker class. Handles log queueing and processing.
class LogWorker {
public:
    LogWorker() : _shouldStop(false), _worker(&LogWorker::work, this) {}
    ~LogWorker() { stop(); }

    void pushMessage(LogMessage msg) {
        std::unique_lock<std::mutex> lock(_queueMutex);
        _messageQueue.push_back(msg);
        lock.unlock();
        _condition.notify_one();
    }

private:
    void work() {
        while(!_shouldStop) {
            std::unique_lock<std::mutex> lock(_queueMutex);
            _condition.wait(lock, [this]{ return !_messageQueue.empty(); }); 

            auto msg = _messageQueue.back();
            _messageQueue.pop_back();

            // Process the message here (e.g., write to a file or send to an external service)
        }
    }

    void stop() {
        _shouldStop = true;
        _condition.notify_all();
        _worker.join();
    }

    std::vector<LogMessage> _messageQueue;
    std::mutex _queueMutex;
    std::condition_variable _condition;

    bool _shouldStop;
    std::thread _worker;
};
```

