```C
// Source file (data_streamer.c)
#include "data_streamer.h"
#include <stdlib.h>
#include <pthread.h>

static StreamConfig config;
static StreamCallback callback;

static pthread_t thread;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
volatile int running = 0; // Protected by 'lock'

// Thread function for processing data
void* process(void* arg) {
    uint32_t* buffer = malloc(sizeof(uint32_t) * 1024);
    size_t count = 0;

    while (running) {
        // Replace with actual data source
        uint32_t newData;

        if (newData > config.threshold) {
            buffer[count++] = newData;

            if (count == sizeof(buffer)/sizeof(uint32_t)) {
                pthread_mutex_lock(&lock);
                callback(buffer, count);
                pthread_mutex_unlock(&lock);

                free(buffer);
                buffer = malloc(sizeof(uint32_t) * 1024);
            }
        }
    }

    // Process remaining data before exiting
    if (count > 0) {
        pthread_mutex_lock(&lock);
        callback(buffer, count);
        pthread_mutex_unlock(&lock);
    }

    free(buffer);
    return NULL;
}

void init_streamer(StreamConfig cfg, StreamCallback cb) {
    config = cfg;
    callback = cb;
}

void start_stream() {
    running = 1;
    pthread_create(&thread, NULL, process, NULL);
}

void stop_stream() {
    if (running) {
        running = 0;
        pthread_join(thread, NULL);
    }
}
```
This code provides the basic structure for a data streamer. This is by no means complete - it's missing many elements such as handling network timeouts or malformed data packets, memory management, and comprehensive unit tests. For each of these features, you would likely need to write additional functions and add more complexity.
