```python
class LogManager(object):
    def __init__(self):
        self.loggers = {}
        self.lock = threading.Lock()

    def add_logger(self, name, logger):
        with self.lock:
            if name not in self.loggers:
                self.loggers[name] = logger

    def remove_logger(self, name):
        with self.lock:
            if name in self.loggers:
                del self.loggers[name]

    def log(self, message, level='INFO', destination=None):
        for name, logger in self.loggers.items():
            if not destination or logger.destination == destination:
                threading.Thread(target=logger.log, args=(message, level)).start()
```
