const bodyParser = require('body-parser');
const Sequelize = require('sequelize');
const bibleAnalyzer = require('./bibleAnalyzer');

// Create an instance of Express
const app = express();
app.use(bodyParser.json());

// Connect to the database
const sequelize = new Sequelize(process.env.DATABASE_URL);

// Define a model for books in the Bible
const Book = sequelize.define('book', {
  title: Sequelize.STRING,
});

app.post('/analyze-text', async (req, res) => {
  try {
    const text = req.body.text;
    if (!text) {
      return res.status(400).json({ error: 'Invalid input' });
    }

    // Analyze the text and get references to Old and New Testament books
    const results = await bibleAnalyzer.analyzeText(text);

    // Update multiple dialog fields with the analysis results in a transaction
    const t = await sequelize.transaction();
    try {
      for (let i = 0; i < results.length; ++i) {
        const book = results[i];
        // Assuming that 'dialogField' is an array of dialog fields to be updated, 
        // you may need a different way to access these fields depending on your actual app setup
        await sequelize.query(`UPDATE dialogFields SET bookReferenceCount = bookReferenceCount + 1 WHERE title = $book`, { transaction: t });
      }

      await t.commit();
    } catch (error) {
      await t.rollback();
      return res.status(500).json({ error: 'Error updating dialog fields' });
    }

    res.json(results);
  } catch (error) {
    console.error('Failed to analyze text', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = app;
```

