["```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>

class DistributedPriorityQueue {
public:
    explicit DistributedPriorityQueue(int capacity) : capacity_(capacity) {}
    ~DistributedPriorityQueue() = default;

    void AddElement(const std::string& element);
    std::string GetHighestPriority();
    bool IsEmpty();
    bool IsFull();
    void ExpandCapacity(int new_capacity);
    int GetSize();
    int GetCurrentLoadFactor();

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    std::vector<std::string> queue_;
    const int capacity_;
};

void DistributedPriorityQueue::AddElement(const std::string& element) {
    std::unique_lock<std::mutex> lock(mutex_);
    condition_.wait(lock, [this] { return !IsFull(); });

    queue_.push_back(element);
    std::sort(queue_.begin(), queue_.end()); // Ensure highest priority is at the end of vector.

    lock.unlock();
    condition_.notify_all();
}

std::string DistributedPriorityQueue::GetHighestPriority() {
    std::unique_lock<std::mutex> lock(mutex_);
    condition_.wait(lock, [this] { return !IsEmpty(); });

    auto highest_priority = queue_.back();  // Assuming higher numbers have higher priority.
    queue_.pop_back();

    lock.unlock();
    condition_.notify_all();
    return highest_priority;
}

bool DistributedPriorityQueue::IsEmpty() {
    std::lock_guard<std::mutex> lock(mutex_);
    return queue_.empty();
}

bool DistributedPriorityQueue::IsFull() {
    std::lock_guard<std::mutex> lock(mutex_);
    return queue_.size() >= capacity_;
}

void DistributedPriorityQueue::ExpandCapacity(int new_capacity) {
    std::unique_lock<std::mutex> lock(mutex_);
    condition_.wait(lock, [this] { return GetCurrentLoadFactor() < 0.75; }); // Load factor threshold for expand.

    capacity_ = new_capacity; 
}

int DistributedPriorityQueue::GetSize() {
    std::lock_guard<std::mutex> lock(mutex_);
    return queue_.size();
}

int DistributedPriorityQueue::GetCurrentLoadFactor() {
    std::lock_guard<std::mutex> lock(mutex_);
    return static_cast<float>(queue_.size()) / capacity_;  // Load factor calculation.
}
```
This is a simple example of priority queue in C++, where each element is string and the higher value has higher priority (in this case it's sorting order). For more complex scenarios like handling distributed servers or game engine integration specific methods would be required.
"]

["This task is quite complex and would require a large amount of code, which goes beyond the scope of this platform. However, I can provide you with some basic classes/structures that could be used as starting points in your C++ program to manage a hero's combat abilities. Please note that real-time data integration, concurrency and scalability, performance optimization, error handling, logging and monitoring, security measures are much more complex topics requiring careful design and planning.

```cpp
#include <vector>
#include <string>
#include <chrono>

// Forward declaration to avoid circular dependency
class Hero;

struct Ability {
    std::string name;
    int cooldown; // in seconds
    std::chrono::steady_clock::time_point lastUsed = std::chrono::steady_clock::now(); 
    virtual void execute(Hero& hero) = 0; // Pure virtual function to be overridden by each ability type
};

class PrimaryAttack : public Ability {
public:
    void execute(Hero& hero);
};

class SecondaryAttack : public Ability {
public:
    void execute(Hero& hero);
};

// Hero class to manage the abilities and cooldowns
class Hero {
private:
    std::vector<Ability*> abilities; // Vector of pointers to allow for polymorphic behavior

public:
    void addAbility(Ability* ability) { abilities.push_back(ability); }

    bool canUseAbility(Ability& ability) const {
        auto now = std::chrono::steady_clock::now();
        return (now - ability.lastUsed).count() >= ability.cooldown; // Check if cooldown has passed
    }

    void useAbility(Ability& ability) {
        if (canUseAbility(ability)) {
            ability.execute(*this); 
            ability.lastUsed = std::chrono::steady_clock::now(); // Update last used time
        }
    }
};
```
This is a very basic example and does not include many features you might need in an actual MOBA game, such as networking for multiplayer support or real-time data integration. Also note that C++'s type system and RAII principles mean that managing resources (like API connections) can be tricky without careful design and handling of exceptions. Finally, please do not forget to write extensive tests for your code to ensure its correctness.
