```C
#include <pthread.h>
#include <curl/curl.h>
#include <json-c/json.h> // Consider using a library like json-c for JSON parsing

struct task {
    int id;
    char* endpoint;
    struct json_object *requestBody;
    //... other fields as required by the API 
};

void *worker(void *arg) {
    struct task *t = (struct task *)arg;

    CURL *curl = curl_easy_init();
    if(curl) {
        CURLcode res;

        // Setup API endpoint, request method and headers
        curl_easy_setopt(curl, CURLOPT_URL, t->endpoint);
        //... other options as required by the API 

        // Perform request
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        // Handle response and update task status or results...

        curl_easy_cleanup(curl);
    }

    return NULL;
}

int main() {
    pthread_t threads[500];

    // Prepare tasks...

    for (int i = 0; i < 500; i++) {
        struct task *t = malloc(sizeof(*t));
        t->id = i;

        pthread_create(&threads[i], NULL, worker, t);
    }

    for (int i = 0; i < 500; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
