@RestController
public class ProductRecommendationController {

    private final UserService userService;
    private final RecommendationService recommendationService;

    @Autowired
    public ProductRecommendationController(UserService userService, RecommendationService recommendationService) {
        this.userService = userService;
        this.recommendationService = recommendationService;
    }

    @GetMapping("/users/{id}/product-recommendations")
    public List<Product> getRecommendations(@PathVariable("id") String userId) {
        return userService.findById(userId)
            .map(recommendationService::getRecommendationsForUser)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such User"));
    }
}
