However, I will provide a simplified example using the ZeroMQ library for messaging, RabbitMQ for message queuing, and MongoDB for data storage in C++. The design pattern used here is Publish/Subscribe model for IoT devices and social media APIs integration, whereas financial market feeds can be handled by a request/response pattern. 

```cpp
#include <zmq.hpp>
#include <mongocxx/client.hpp>
#include <mongocxx/instance.hpp>
#include <rabbitmq-c/amqp_tcp_socket.h>
#include <rabbitmq-c/consumer.h>
#include <iostream>

// IoT devices and social media APIs data processing
void processIoTSocialData() {
    zmq::context_t context(1);
    zmq::socket_t subscriber(context, ZMQ_SUB);

    // Connect to the socket for IoT devices or social media APIs
    // For simplicity, assume we're connecting to localhost and port 5563
    subscriber.connect("tcp://localhost:5563");

    while(true) {
        zmq::message_t update;
        subscriber.recv(&update);

        // Process the data here...
    }
}

// Financial market feeds processing
void processFinancialFeed() {
    amqp_connection_state_t conn = amqp_new_connection();
    amqp_socket_t *socket = amqp_tcp_socket_new(conn);

    // Open a connection to the RabbitMQ server
    amqp_login(conn, "/", 0, 131072, AMQP_LOGIN_ROLE, 0, AMQP_SASL_METHOD_PLAIN);

    // Create a queue to receive data from the financial market feeds
    amqp_queue_declare(conn, /* channel */ 1, amqp_cstring_bytes("financial.feed"), false, true, false, false, amqp_empty_table);

    while (true) {
        amqp_frame_t frame;
        int result = amqp_simple_wait_frame(conn, &frame);

        if (result < 0) break;

        // Process the data here...
    }
}

// Data storage and validation
void storeData() {
    mongocxx::instance inst{};
    mongocxx::client conn{mongocxx::uri{}};
    auto db = conn["iot_data"];

    while (true) {
        // Fetch the data here...

        // Store the processed data in MongoDB
        bsoncxx::builder::stream::document document{};
        document << "name" << "John Doe" << "age" << 30;

        db["users"].insert_one(document.view());
    }
}

int main() {
    std::thread t1(processIoTSocialData);
    std::thread t2(processFinancialFeed);
    std::thread t3(storeData);

    t1.join();
    t2.join();
    t3.join();
}
```

