#include <sqlite3.h>

void store_record(Record record) {
    sqlite3 *db;
    char *errMsg = 0;
    int rc = sqlite3_open("records.db", &db);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", 
                sqlite3_errmsg(db));
        sqlite3_close(db);

        return;
    }

    char *sql = sqlite3_mprintf("INSERT INTO records VALUES (%d, %ld)", 
                                record.key, record.offset);

    rc = sqlite3_exec(db, sql, NULL, 0, &errMsg);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", errMsg);
        sqlite3_free(errMsg);
    }

    sqlite3_close(db);
}
