['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <curl/curl.h>
#include <jansson.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char* RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct doublyLinkedList {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct doublyLinkedList* next;
    struct doublyLinkedList* prev;
} DoublyLinkedList;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

DoublyLinkedList* tokenCache[1024];
time_t expirationTimeCache[1024];
CURL *curl;
int retryCount = 0;

void init() {
    curl = curl_easy_init();
}

static size_t writeCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char*)userp)[size*nmemb] = 0;
    return size*nmemb;
}

int validateOAuth2Token(const char* tokenUrl) {
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "Accept: application/json");

    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_URL, tokenUrl);

    char response[4096];
    memset(response, 0, sizeof(response));

    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);

    int attemptCount = 1;
    while (retryCount < 5 && curl_easy_perform(curl) != CURLE_OK) {
        sleep((int)pow(2.0, retryCount++)); // exponential backoff
        if (attemptCount >= 5) return -1;  // return error after five attempts.
    }

    json_t *root = json_loads(response, 0, NULL);
    json_t *tokenTypeJson = json_object_get(root, "token_type");
    if (!json_is_string(tokenTypeJson) || strcmp(json_string_value(tokenTypeJson), "Bearer")) return -1; // invalid token type.

    json_t *expiresInJson = json_object_get(root, "expires_in");
    if (!json_is_integer(expiresInJson) || json_integer_value(expiresInJson) < 0) return -1;  // invalid expires_in.

    json_decref(root);

    return 0;
}
```
']

