typedef struct {
    // your data structure here
} NFAPI_CRC_INDICATION_PDU_T;

// Global lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore;

// Doubly-linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL;
Node* tail = NULL;

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    // Create a new node
    Node* temp = (Node*) malloc(sizeof(Node));
    temp->data = data;
    temp->next = NULL;
    temp->prev = tail;

    if(tail == NULL) {
        head = temp;
    } else {
        tail->next = temp;
    }

    tail = temp;

    pthread_mutex_unlock(&lock);
}

// Your function prototype here
