int storeDataInDb(NFAPI_CRC_INDICATION_PDU_T data) {
    int connId = -1;
    pthread_mutex_lock(&dbConnPool.lock); // Lock the connection pool to ensure thread safety
    for(int i = 0; i < 10; i++) {
        if(!isConnectionActive(dbConnPool.connections[i])) { // Check if connection is active or not
            connId = i;
            break;
        }
    }

    if(connId == -1) { // If all connections are busy, wait until one becomes free
        pthread_cond_t cond = PTHREAD_COND_INITIALIZER; 
        pthread_mutex_lock(&dbConnPool.lock);

        while(connId == -1) {
            pthread_cond_wait(&cond, &dbConnPool.lock); // Wait until connection becomes free

            for(int i = 0; i < 10; i++) {
                if(!isConnectionActive(dbConnPool.connections[i])) { // Check if connection is active or not
                    connId = i;
                    break;
                }
            }
        }

        pthread_mutex_unlock(&dbConnPool.lock); 
    }

    storeData(data, dbConnPool.connections[connId]); // Store data in the database
    markConnectionActive(dbConnPool.connections[connId], false); // Mark connection as busy after storing data
