```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    void* value;
} Record;

// The central data structure is a hashmap
Record** records; 
int recordCount = 0;
pthread_mutex_t lock; // Mutex for thread safety

void insert(Record* record) {
    pthread_mutex_lock(&lock);

    if (record->key < 0 || record->key >= INT_MAX) {
        printf("Invalid key value\n");
        return;
    }

    // Insert the record into the records array at the given index
    records[record->key] = record;
    ++recordCount;

    pthread_mutex_unlock(&lock);
}

Record* lookup(int key) {
    if (key < 0 || key >= INT_MAX) {
        printf("Invalid key value\n");
        return NULL;
    }

    // Look up the record in the records array at the given index
    return records[key];
}

void delete(int key) {
    pthread_mutex_lock(&lock);

    if (key < 0 || key >= INT_MAX) {
        printf("Invalid key value\n");
        return;
    }

    // Delete the record from the records array at the given index
    free(records[key]);
    --recordCount;

    pthread_mutex_unlock(&lock);
}
```

This is a very basic example and does not take into account many of your requirements, such as concurrency safety or error handling. A complete solution would be much more complex and lengthy, and likely involve using external libraries and/or tools for specific features like database integration or logging. It's recommended to approach this task in phases, starting with the basic data structure and gradually adding complexity as you get each part working correctly.
