    // Lock to avoid race conditions
    pthread_mutex_lock(&lock);

    // Measure performance before operation
    struct rusage start, end;
    getrusage(RUSAGE_SELF, &start);

    // Get the extension and append timestamp and random number to it
    char* unique_filename = NULL;
    while (1){
        unique_filename = append_timestamp_and_random(filename);

        // Check for network failure
        if (!network_operation(max_retries, time_window)) {
            handle_error(errno, "Network operation failed");
        } else {
            break;
        }
    }

    // Unlock after operation
    pthread_mutex_unlock(&lock);

    getrusage(RUSAGE_SELF, &end);
    measure_performance(&start, &end);

    return unique_filename;
}
