// Structure to hold file related information
typedef struct {
    char* url;  // Cloud storage API URL
    char* output_file;  // Output filename
} FileInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Lock for thread safety

// Write function callback from libcurl
size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

// Thread function to download and process file
void* processFile(void* arg) {
    FileInfo* fi = (FileInfo*)arg;

    CURL *curl_handle;
    FILE *pagefile;

    curl_global_init(CURL_GLOBAL_ALL);
    curl_handle = curl_easy_init();
    curl_easy_setopt(curl_handle, CURLOPT_URL, fi->url);

    // Setup write function and file pointer
    pagefile = fopen(fi->output_file, "wb");
    if (pagefile) {
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, pagefile);

        // Perform the request, res will get the return code
        CURLcode res = curl_easy_perform(curl_handle);

        // Check for errors
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
    } else {
        fprintf(stderr, "Failed to open the file.\n");
    }

    // Cleanup 
    fclose(pagefile);
    curl_easy_cleanup(curl_handle);
    curl_global_cleanup();

    pthread_exit(NULL);
}

int main() {
    FileInfo file1 = {"http://cloudstorage.com/file1", "output1.bin"};
    FileInfo file2 = {"http://cloudstorage.com/file2", "output2.bin"};

    pthread_t thread1, thread2;

    // Create threads to download and process files in parallel
    if (pthread_create(&thread1, NULL, processFile, &file1) != 0) {
        fprintf(stderr, "Error creating thread 1\n");
        return 1;
    }

    if (pthread_create(&thread2, NULL, processFile, &file2) != 0) {
        fprintf(stderr, "Error creating thread 2\n");
        return 1;
    }

    // Wait for the threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
```
