#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <curl/curl.h>

typedef struct {
    CURL *handle;
    char *url;
} RequestData;

void* perform_request(void *arg) {
    RequestData *data = (RequestData*)arg;
    CURLcode res;

    curl_easy_setopt(data->handle, CURLOPT_URL, data->url);
    res = curl_easy_perform(data->handle);

    if(res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }

    curl_easy_cleanup(data->handle);
    free(data);

    return NULL;
}

void send_request(const char *url) {
    pthread_t thread;
    RequestData *data = malloc(sizeof(RequestData));

    data->handle = curl_easy_init();
    if(!data->handle) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        free(data);
        return;
    }

    data->url = strdup(url);

    if(pthread_create(&thread, NULL, perform_request, data) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        curl_easy_cleanup(data->handle);
        free(data->url);
        free(data);
    } else {
        pthread_detach(thread); // Let the request run independently
    }
}
```

This code uses libcurl to perform a GET request on a given URL. The request is handled in a separate thread so that it doesn't block the main program flow. The `send_request` function accepts a URL, initializes a new libcurl handle and data structure for the thread, and creates a new thread to run the request on.

