```cpp
class ResourcePool {
  std::mutex mtx;
  std::vector<Resource> pool;
public:
  void borrowResource(Client c){
    lock_guard<std::mutex> lock(mtx); // Ensure thread-safety
    if(!pool.empty()){
      Resource r = pool.back();
      pool.pop_back();
      c.use(r);
    } else {
      // Handle resource exhaustion scenario
    }
  }

  void returnResource(Client c, Resource r){
    lock_guard<std::mutex> lock(mtx); // Ensure thread-safety
    pool.push_back(r);
    c.free();
  }
};
```
