const fs = require('fs').promises;
const path = require('path');

async function processDirectory(directoryPath) {
  const files = await fs.readdir(directoryPath);
  for (let file of files) {
    const filePath = path.join(directoryPath, file);
    const stats = await fs.stat(filePath);

    if (stats.isDirectory()) {
      processDirectory(filePath); // Recursively processes subdirectories
    } else {
      // Asynchronous processing of files here
      console.log(`Processing ${filePath}...`);

      const data = await fs.readFile(filePath, 'utf-8');  // Fake async operation
      setTimeout(() => {
        console.log(`Finished processing ${filePath}.`);
      }, 1000);  // Simulate long asynchronous operation with setTimeout
    }
  }
}

processDirectory('./test-directory');
```
