using System;
using System.Threading;

namespace DynamicValueProvider 
{
    public class RandomGenerator : IDisposable
    {
        private static ThreadLocal<Random> randomWrapper = new ThreadLocal<Random>(() =>
        {
            return new Random();
        });

        private bool _disposed = false;

        public int Next(int minValue, int maxValue) 
        {
            return randomWrapper.Value.Next(minValue, maxValue);
        }

        // Implement IDisposable
        protected virtual void Dispose(bool disposing)
        {
            if (!_disposed)
            {
                if (disposing) 
                {
                    // Dispose managed resources.
                }

                _disposed = true;
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
    }
}
```
This library creates a thread-safe way to generate random numbers between user-defined bounds. Error handling and logging mechanisms should also be included in the library, but this is just an example of how you can start creating your library. 

