['Here is a simple C implementation of dynamic memory allocation for your arrays and structure. This code does not incorporate all functionalities described in your task but serves as a starting point. 

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int main() {
    long *offsets;
    int *keys, num_elements = 10; // Replace 10 with actual size

    srand(time(NULL)); // Initialize random number generator

    offsets = malloc(num_elements * sizeof(*offsets));
    if (offsets == NULL) {
        return -1; // Allocation failed
    }

    keys = malloc(num_elements * sizeof(*keys));
    if (keys == NULL) {
        free(offsets);
        return -1; // Allocation failed
    }

    Record *records = malloc(num_elements * sizeof(*records));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return -1; // Allocation failed
    }

    int min = 0, max = 99; // Replace with your range
    for (int i = 0; i < num_elements; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```
