from kafka import KafkaProducer, KafkaConsumer
import boto3
import json
import time
import logging
from botocore.exceptions import BotoCoreError, ClientError

class KafkaClient:
    def __init__(self, bootstrap_servers):
        self.producer = KafkaProducer(bootstrap_servers=bootstrap_servers, value_serializer=lambda v: json.dumps(v).encode('utf-8'))

    def send_message(self, topic, message):
        self.producer.send(topic, message)
        self.producer.flush()

class S3Client:
    def __init__(self, bucket_name):
        self.s3 = boto3.resource('s3')
        self.bucket_name = bucket_name

    def upload_file(self, file_name, object_name=None):
        if object_name is None:
            object_name = file_name
        try:
            response = self.s3.Bucket(self.bucket_name).upload_file(file_name, object_name)
            return True
        except ClientError as e:
            logging.error(e)
            return False

class LambdaClient:
    def __init__(self):
        self.lambda_client = boto3.client('lambda')

    def invoke_function(self, function_name, payload):
        response = self.lambda_client.invoke(FunctionName=function_name, Payload=json.dumps(payload))
        return json.loads(response['Payload'].read().decode('utf-8'))
``` 
