class Buffer {
public:
    explicit Buffer(size_t initialSize = 0) : buffer_(initialSize){}

    void addChunk(const uint8_t* chunk, size_t chunkSize) {
        size_t currentSize = buffer_.size();
        buffer_.resize(currentSize + chunkSize);
        std::copy(chunk, chunk + chunkSize, &buffer_[currentSize]);
    }

    uint8_t* getData() {  // Returns a pointer to the data.
        return &buffer_[0];
    }

private:
