class Processor {
private:
    std::unordered_map<std::string, std::shared_ptr<SensorData>> cache;
    std::mutex mtx;
    std::condition_variable cond;
    std::queue<std::function<void()>> tasksQueue;
    std::atomic<bool> isRunning = {true};
    std::vector<std::thread> threads;
public:
    Processor(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this] {
                while (isRunning) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(mtx);
                        cond.wait(lock, [this] { return !tasksQueue.empty(); });
                        task = std::move(tasksQueue.front());
                        tasksQueue.pop();
                    }
                    if (task) {
                        task();
                    }
                }
            });
        }
    }
    ~Processor() {
        isRunning = false;
        cond.notify_all();
        for(std::thread &t: threads){
            t.join();
        }
    }

    void processAndCacheSensorData(const SensorData& data) {
