    strncpy(msg->eps_id, eps_id, 10);
    pthread_mutex_unlock(&global_lock); // Release the lock after modification is done

    return msg;
}

void delete_message(LTE_MME_MESSAGE_T *msg) {
    pthread_mutex_lock(&global_lock); 
    free(msg);
    pthread_mutex_unlock(&global_lock); 
}

char* get_eps_id(LTE_MME_MESSAGE_T *msg) {
    char *eps_id;

    pthread_mutex_lock(&global_lock); 
    eps_id = msg->eps_id;
    pthread_mutex_unlock(&global_lock); 

    return eps_id;
}
