#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    // Fields for EPS Mobility Management messages, Non-Access Stratum (NAS) messages, and S-GW contexts.
} LTE_MME_MESSAGE_T;

// Custom dynamic array structure
typedef struct {
    int size;
    LTE_MME_MESSAGE_T* data;
    pthread_mutex_t mutex;  // For thread safety
} DynamicArray;

DynamicArray* createArray(int initialSize) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    arr->data = malloc(initialSize * sizeof(LTE_MME_MESSAGE_T));
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);  // Initialize mutex
    return arr;
}

void addMessage(DynamicArray* arr, LTE_MME_MESSAGE_T msg) {
    pthread_mutex_lock(&arr->mutex);
    arr->data[arr->size++] = msg;  // Copy message into array
    pthread_mutex_unlock(&arr->mutex);
}

