```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int main() {
    srand(time(NULL)); // Initialize random seed

    long* offsetValues = malloc(sizeof(long) * 10); // For the sake of example, let's say we have 10 offset values.
    int* keys = malloc(sizeof(int) * 10); // And similarly, 10 key values.

    for (int i = 0; i < 10; ++i) {
        offsetValues[i] = rand(); // Fill with random numbers.
        keys[i] = rand();
    }

    Record* records = malloc(sizeof(Record) * 10); // Allocate memory for 10 Records.

    for (int i = 0; i < 10; ++i) {
        records[i].value = rand() % 100 + 1; // Fill each record with a random value between 1 and 100.
    }

    free(offsetValues);
    free(keys);
    free(records);

    return 0;
