import hashlib
from concurrent import futures
from external_api import ExternalAPI
from cloud_providers import CloudProviders
from retry_strategy import RetryStrategy
from data_streaming import DataStreamer

class FileProcessor:
    def __init__(self):
        self.external_api = ExternalAPI()
        self.cloud_provider = CloudProviders()
        self.retry_strategy = RetryStrategy()
        self.data_streamer = DataStreamer()

    @staticmethod
    def get_file_metadata(filepath):
        metadata = {}
        with open(filepath, 'rb') as f:
            data = f.read()
            sha256hash = hashlib.sha256(data).hexdigest()
            md5hash = hashlib.md5(data).hexdigest()
            metadata['size'] = os.path.getsize(filepath)
            metadata['sha256_hash'] = sha256hash
            metadata['md5_hash'] = md5hash
        return metadata

    def process_large_files(self, filepaths):
        with futures.ThreadPoolExecutor() as executor:
            future_to_filepath = {executor.submit(self._process_file, fp): fp for fp in filepaths}
            for future in futures.as_completed(future_to_filepath):
                filepath = future_to_filepath[future]
                try:
                    data = future.result()
                except Exception as exc:
                    print('%r generated an exception: %s' % (filepath, exc))
                else:
                    self._enrich_metadata(data)

    def _process_file(self, filepath):
        metadata = self.get_file_metadata(filepath)
        return metadata

    def _enrich_metadata(self, metadata):
        external_api_resp = self._call_external_api(metadata)
        metadata['external_info'] = external_api_resp

    def _call_external_api(self, metadata):
        return self.retry_strategy.execute(self.external_api.get_data, metadata)

    def send_to_cloud(self, filepath):
