class StreamCollector {
    constructor(url) {
        this.apiUrl = url;
        this.stream = null;
        this.buffer = [];
        this.isPaused = false;
    }

    start() {
        this.stream = fetch(this.apiUrl).then((response) => response.body);

        const reader = this.stream.getReader();
        while (true) {
            let chunk, done = await reader.read();

            if (done) break;
            else this.buffer.push(chunk);

            // Handle pausing/resuming logic here...
        }
    }

    pause() {
        this.isPaused = true;
        reader.cancel();
    }

    resume() {
