```cpp
#include <mutex>
#include <vector>
#include <thread>
#include <optional>
#include <atomic>
#include <algorithm>

struct TELEMETRY_DATA_POINT_T {
    // fields...
};

class TelemetryDataPointStore {
public:
    void add(const TELEMETRY_DATA_POINT_T& data) {
        std::lock_guard<std::mutex> lock(m);
        dataPoints.push_back(data);
    }

    bool remove(size_t index) {
        std::lock_guard<std::mutex> lock(m);
        if (index >= dataPoints.size()) return false;
        dataPoints.erase(dataPoints.begin() + index);
        return true;
    }

    std::optional<TELEMETRY_DATA_POINT_T> get(size_t index) const {
        std::lock_guard<std::mutex> lock(m);
        if (index >= dataPoints.size()) return {};
        return dataPoints[index];
    }

private:
    mutable std::mutex m;
    std::vector<TELEMETRY_DATA_POINT_T> dataPoints;
};
```

The `TelemetryDataPointStore` class provides thread-safe methods for adding, removing and retrieving telemetry data points. Note that the `get()` method returns a `std::optional<TELEMETRY_DATA_POINT_T>` which can either contain a value or be empty if no such element exists at the given index.

For concurrency control, this code uses standard C++17's `std::mutex` and `std::lock_guard` for simplicity. A more sophisticated implementation might use `std::shared_timed_mutex` in combination with `std::shared_lock` to allow multiple threads to read the data concurrently while only one thread can write it, reducing contention on the mutex.

