    // Create a WebSocket connection to the resolved endpoint
    boost::asio::ssl::stream<boost::asio::ip::tcp::socket> ws(ioContext, boost::asio::ssl::context::tlsv12_client);
    boost::asio::connect(ws.lowest_layer(), endpoints);

