["Creating a full library is beyond the capabilities of this platform. However, I can guide you on how to start building your library by providing some pseudo code, which can be used as a base for further implementation. Please note that C does not provide advanced OOP features like classes and inheritance. Hence, we'll use function pointers (similar to callbacks) or preprocessor macros (although it's considered as bad practice in modern programming).

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

// Define a structure for message storage, could be replaced by a linked list/binary tree
typedef struct {
    int id;
    char eps_message[256];
    char nas_message[1024];
    char sgw_context[256];
} MMEMessage;

// Define a structure for array of messages
typedef struct {
    MMEMessage *messages;
    size_t length;
    size_t capacity;
    pthread_mutex_t lock; // to ensure thread safety
} DynamicArray;

DynamicArray* create_array(size_t capacity) {
    DynamicArray *arr = malloc(sizeof(*arr));
    arr->messages = calloc(capacity, sizeof(MMEMessage));
    arr->length = 0;
    arr->capacity = capacity;
    pthread_mutex_init(&arr->lock, NULL); // initialize the lock
    return arr;
}

void insert(DynamicArray *arr, MMEMessage message) {
    pthread_mutex_lock(&arr->lock);  // acquire the lock before accessing shared data

    if (arr->length == arr->capacity) {
        // Resize the array and copy previous elements to new memory location
        size_t newCapacity = arr->capacity * 2;
        MMEMessage *newMessages = calloc(newCapacity, sizeof(MMEMessage));
        memcpy(newMessages, arr->messages, arr->length * sizeof(MMEMessage));

        // Free old memory and assign new array
        free(arr->messages);
        arr->capacity = newCapacity;
        arr->messages = newMessages;
    }

    // Insert the message at end
    arr->messages[arr->length++] = message;

    pthread_mutex_unlock(&arr->lock);  // release lock after accessing shared data
}

MMEMessage get(DynamicArray *arr, size_t index) {
    assert(index < arr->length);
    pthread_mutex_lock(&arr->lock);
    MMEMessage message = arr->messages[index];
    pthread_mutex_unlock(&arr->lock);

    return message;
}
```
