['Here's a basic structure of what your application might look like:

```jsx
// app.js
const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const NodeCache = require( "node-cache" );
const apiService = require('./services/apiService');
const logger = require('./utils/logger');

const app = express();
app.use(express.json());

// Create a cache object 
const myCache = new NodeCache({ stdTTL: 100, checkperiod: 120 });

async function processDirectory(directoryPath) {
    const files = await fs.readdir(directoryPath);

    // Using Promise.all for concurrency processing of multiple files
    await Promise.all(files.map(processFile));
}

async function processFile(filePath) {
    if (!path.extname(filePath).match(/^.(jpg|png|gif)$/)) return;

    const fileStat = await fs.stat(filePath);
    const cachedValue = myCache.get(filePath);

    // Use cached value if available
    if (cachedValue) {
        logger.info(`Using cache for ${filePath}`);
        return cachedValue;
    }

    let result;
    try {
        const metadata = await apiService.getMetadata(fileStat);
        // Adding result to the cache 
        myCache.set(filePath, metadata);
        logger.info(`File processed: ${filePath}`);
        result = metadata;
    } catch (e) {
        logger.error(`Error while processing file ${filePath}: ${e.message}`);
    }

    return result;
}

// Expose an endpoint to trigger the directory processing
app.post('/process', async (req, res) => {
    try {
        await processDirectory(req.body.directoryPath);
        res.sendStatus(200);
    } catch (e) {
        logger.error(`Error while processing directory: ${e.message}`);
        res.status(500).json({ error: e.message });
    }
});

app.listen(3000, () => console.log('Server running on port 3000'));
