Let's create a Node.js application to consume REST APIs asynchronously and handle rate limiting using the `axios-rate-limit` library. Then we will use a Kafka queue for processing data asynchronously with Apache Kafka:

```javascript
const axios = require('axios');
const rateLimit = require('axios-rate-limit');
const { Kafka } = require('kafkajs');

// Rate limit REST API requests
const http = rateLimit(axios.create(), { maxRPS: 10 });

async function consumeAPI() {
  try {
    const response = await http.get('https://api.example.com/data');
    return response.data;
  } catch (error) {
    console.error(`Error consuming REST API: ${error}`);
  }
}

// Create Kafka producer
const kafka = new Kafka({
  clientId: 'my-app',
  brokers: ['kafka1:9092', 'kafka2:9092'] // replace with your Kafka broker addresses
});

const producer = kafka.producer();

async function produceToKafka(data) {
  try {
    await producer.connect();
    await producer.send({
      topic: 'sensor-data',
      messages: [{ value: JSON.stringify(data) }],
    });
  } catch (error) {
    console.error(`Error producing to Kafka: ${error}`);
  } finally {
    await producer.disconnect();
  }
}

// Consume REST API and produce data to Kafka
async function main() {
  const data = await consumeAPI();
  if (data) {
    await produceToKafka(data);
  }
}

main().catch(console.error);
```

