        while (true) {
            Document document;
            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this](){ return stopFlag || !documentsQueue.empty(); });
                if (stopFlag && documentsQueue.empty()) return;
                document = documentsQueue.front();
                documentsQueue.pop();
            }

            // Process the document using third-party services and libraries
        }
    }
};
