#include <thread>

struct ProductMetadata {
    int id;
    double price;
    int inventoryLevel;
};

class MetadataStorage {
private:
    std::unordered_map<int, ProductMetadata> dataStore;  // Assuming product ID as unique key
    mutable std::shared_timed_mutex metadataMutex;
public:
    void addProduct(const ProductMetadata& product) {
        std::lock_guard<std::shared_timed_mutex> lock(metadataMutex);
        if (dataStore.find(product.id) == dataStore.end()) // Checking for unique IDs
            dataStore[product.id] = product;
    }

    ProductMetadata getProduct(int id) const {
        std::shared_lock<std::shared_timed_mutex> lock(metadataMutex);
        auto itr = dataStore.find(id);
        if (itr != dataStore.end()) 
            return itr->second;
        // Return an empty metadata in case the product does not exist
        return { -1, -1.0, -1 };
    }

    void processDataAsync(const ProductMetadata& product) {
        std::thread t(&MetadataStorage::addProduct, this, product);
        t.detach();  // Running in background
    }
};
```
This code demonstrates a class `MetadataStorage` that stores and retrieves product metadata concurrently using a shared mutex for better performance. Asynchronous data ingestion is handled by spawning a new thread for each incoming product data, and detached to avoid blocking the main process. The use of unordered_map ensures O(1) complexity for both add and get operations. However, this is just a basic idea and real-world applications will require much more complex error handling, logging, validation checks, etc. 

