struct ProcessingResult {
    int totalUniqueIds;
    double averageLogSizeInBytes;
    double timeTakenInMs;
};

ProcessingResult batchProcessAndAggregateLogs(std::vector<LoggingService*>& services, int batchSize) {
    auto start = std::chrono::high_resolution_clock::now();

    ProcessingResult result;
    int totalCount = 0;
    double totalBytes = 0.0;
    std::unordered_set<std::string> ids;

    // Assuming services are accessed sequentially for simplicity. 
    // In a real-world scenario, you might want to use async/await or similar constructs for better performance.
    for(LoggingService* service : services) {
        auto logs = service->getLogs(batchSize);

        for (auto& log : logs) {
            std::lock_guard<std::mutex> lock(mtx); // Ensure thread safety.

            if (ids.find(log.id) == ids.end()) { // New unique ID.
                ids.insert(log.id);
                totalCount++;
            }

            totalBytes += sizeof(log);  // Assuming sizeof gives the size in bytes. Adjust as needed for actual implementation.
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    result.timeTakenInMs = std::chrono::duration<double, std::milli>(end - start).count();
    result.totalUniqueIds = totalCount;
    result.averageLogSizeInBytes = totalBytes / totalCount;  // Assuming average log size is calculated as total bytes divided by number of logs. Adjust as needed for actual implementation.

    return result;
}
```
