using System;
using System.Threading.Tasks;

namespace WebDirManager
{
    public class WebsiteDirectory : IWebsiteDirectory
    {
        private readonly IDependencyInjector _dependencyInjector;
        private readonly IMonitorService _monitorService;

        public WebsiteDirectory(IDependencyInjector dependencyInjector, IMonitorService monitorService)
        {
            _dependencyInjector = dependencyInjector;
            _monitorService = monitorService;
        }

        public async Task<bool> StartAsync(string directoryPath)
        {
            var websiteLoader = _dependencyInjector.ResolveWebsiteLoader();
            var isStartedSuccessfully = await websiteLoader.LoadAndStartFromDirectory(directoryPath);

            if (!isStartedSuccessfully)
                return false;

            _monitorService.Monitor(websiteLoader);

            return true;
        }

        public async Task<bool> AddWebsiteAsync(string websiteAddress, string directoryPath)
        {
            var websiteAdder = _dependencyInjector.ResolveWebsiteAdder();

            try
            {
                await websiteAdder.AddToDirectoryAsync(websiteAddress, directoryPath);

                return true;
            }
            catch (Exception e)
            {
                // Log exception and return false
                _dependencyInjector.ResolveLogger().LogError(e);
                return false;
            }
        }
    }
}
```
