['Here is a C++ code snippet that uses the unordered_map to implement dynamic hash table for storing product metadata. Please note, implementing this solution in real-world e-commerce system would be complex and require more consideration about concurrency control, error handling, performance optimization etc. 

```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
#include <mutex>

struct Product {
    std::string id;
    double price;
    int inventoryLevel;
};

class ProductMetadataStore {
private:
    std::unordered_map<std::string, Product> productMap; // Map from ID to product details.
    std::mutex mapMutex; // Mutex for synchronizing access to the map.

public:
    void addProduct(const Product& product) {
        std::lock_guard<std::mutex> lock(mapMutex); 
        if (productMap.find(product.id) == productMap.end()) {
            // Only insert if the product doesn't already exist in the map.
            productMap[product.id] = product;
        } else {
            std::cerr << "Duplicate product ID: " << product.id << "\n";
        }
    }

    Product getProduct(const std::string& id) {
        std::lock_guard<std::mutex> lock(mapMutex); 
        auto it = productMap.find(id);
        if (it != productMap.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Product not found: " + id);
        }
    }
};
```

