["This is a complex task that can't really be fully implemented in this limited space due to the complexity involved. However, here is a simplified example of the first part: 

```cpp
#include <atomic>
#include <condition_variable>
#include <mutex>
#include <queue>
#include <string>
#include <thread>
#include <vector>

class AsyncQueue {
public:
    explicit AsyncQueue(size_t maxSize) : _maxSize(maxSize) {}
    ~AsyncQueue() { notifyAll(); }

    void put(const std::string &message) {
        if (_messages.size() >= _maxSize) {
            _producerCondVar.wait(_queueMutex, [&]() { return _messages.size() < _maxSize; });
        }

        _messages.push(message);
        notifyAll();
    }

    void get(std::string &message) {
        std::unique_lock<std::mutex> lock(_queueMutex);

        if (_messages.empty()) {
            _consumerCondVar.wait(lock, [&]() { return !_messages.empty(); });
        }

        message = _messages.front();
        _messages.pop();
    }

private:
    void notifyAll() {
        _producerCondVar.notify_all();
        _consumerCondVar.notify_all();
    }

    const size_t _maxSize;
    std::queue<std::string> _messages;
    mutable std::mutex _queueMutex;
    std::condition_variable _producerCondVar, _consumerCondVar;
};
```
This is a simple producer/consumer queue with thread-safe operations and blocking for producers when the queue is full and for consumers when it's empty. 

For the second part, here is an example of how to insert a string after another string in a forward_list:

```cpp
#include <forward_list>

void InsertAfter(std::forward_list<std::string> &list, const std::string &target, const std::string &insert) {
    auto prev = list.before_begin();
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == target) {
            list.insert_after(it, insert);
            return;
        }
        prev = it;
    }
    list.insert_after(prev, insert);
}
```
This function uses a simple loop to find the first occurrence of 'target' in the forward list. When found, it inserts 'insert' after it and returns. If no match is found, it appends 'insert' at the end of the list.
"]

