    {
        var retryPolicy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)));

        await retryPolicy.ExecuteAsync(async () => 
        {
            try
            {
                var response = await _httpClient.PostAsync("your_endpoint", new StringContent(JsonConvert.SerializeObject(newContent), Encoding.UTF8, "application/json"));
                response.EnsureSuccessStatusCode();

                // Implement any other logic that you need to handle successful update here...
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to update content with value: '{newContent}'");
                throw;
            }
        });
    }
}
```

