["Here's an implementation outline of your requirements using Node.js, `axios` for API calls, `readdirp` for directory reading, `lru-cache` for caching, and `dotenv` for environment configuration. 

Please note that this is a high level sketch of the solution and may require additional implementation details to fit your specific requirements. The actual implementation might vary significantly based on what API you're integrating with and how you structure your project.

```javascript
const fs = require('fs');
const path = require('path');
const readdirp = require('readdirp');
const axios = require('axios');
const LRU = require('lru-cache');
require('dotenv').config();

// Setup cache with 50mb max size
const cache = new LRU({max: 1000 * 1024 * 50}); // Cache for metadata
const MAX_CONCURRENT_READS = process.env.MAX_CONCURRENT_READS || 10;
let currentReads = 0;

// Read file metadata from external API
async function readMetadata(file) {
    if (cache.has(file)) return cache.get(file);

    const response = await axios.post('/api/metadata', {path: file});
    cache.set(file, response.data);
    return response.data;
}

// Asynchronously read files from specified directory
async function readFilesFromDir(dir) {
    let queue = [];

    readdirp(dir).on('data', async (entry) => {
        if (currentReads >= MAX_CONCURRENT_READS) return; // Throttle concurrent reads
        currentReads++;

        const metadataPromise = readMetadata(path.join(dir, entry.name));
        queue.push(metadataPromise);
    });

    readdirp.on('warn', console.error);
    readdirp.on('end', () => {
        Promise.allSettled(queue).then(() => currentReads--); // Decrement after each read finishes
    });
}
``` 

This is just a very basic setup, without error handling and tests. You would need to add more details like:

- Error handling: Using `try...catch` blocks around API calls and file reads, and return errors in some way (for example, using promises or events).

- Testing: Consider using libraries like `Jest` for unit testing and integration tests. Write tests that verify correct behavior under different scenarios, including edge cases and error conditions.

- Configuration system: Use `config` package to manage your configuration files based on the environment (development, test, production). 

Remember always to secure sensitive data such as API keys or passwords by not committing them into the repository but rather using environmental variables or a separate config file that's ignored by git.
