    public void establishConnection() throws IOException {
        try {
            // create a socket channel
            socketChannel = SocketChannel.open(new InetSocketAddress("localhost", 80));

            // configure non-blocking mode and turn on TCP_NODELAY for performance
            socketChannel.configureBlocking(false);
            socketChannel.setOption(StandardSocketOptions.TCP_NODELAY, true);

        } catch (IOException e) {
            // Handle error appropriately, such as retrying after a delay or logging the error and shutting down the service gracefully
        } 
    }

    public void sendMessage(String message) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        // put message into byte buffer
        buffer.put(message.getBytes());
        buffer.flip();

        // write to channel
        socketChannel.write(buffer);
    }

    public String receiveMessage() throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        // read from channel into buffer
        int bytesRead = 0;
        while ((bytesRead = socketChannel.read(buffer)) > 0) {
            System.out.println("Received: " + new String(buffer.array(), 0, bytesRead));
        }

        return new String(buffer.array());
    }

