use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;

class ClinicUpdater {
    protected $dbh, $authServiceUrl;

    public function __construct(PDO $dbh, $authServiceUrl) {
        $this->dbh = $dbh;
        $this->authServiceUrl = $authServiceUrl;
    }

    private function getIpAddress() {
        // Implement logic to get IP address here
        return '127.0.0.1';
    }

    public function updateClinic($clinicId, $status) {
        $ip = $this->getIpAddress();

        if(!$this->verifyIP($ip)) 
            throw new Exception("Unable to verify IP", 1);

        $stmt = $this->dbh->prepare('UPDATE clinics SET status=?, last_modified_ip=? WHERE id = ?');

        try {
            $this->dbh->beginTransaction(); // Start transaction
            if(!$stmt->execute([$status, $ip, $clinicId])) 
                throw new Exception("Unable to update clinic", 2);

            $this->dbh->commit(); // Commit transaction
        } catch (Exception $e) {
            $this->dbh->rollBack(); // Rollback on failure
            throw $e;
        }

        return true;
    }

    public function verifyIP($ip) {
        $client = new Client();

        try {
            $response = $client->request('GET', $this->authServiceUrl . "?ip=" . $ip); // Assuming the external service accepts IP as a query parameter
            if ($response->getStatusCode() != 200) 
                return false;
        } catch (RequestException $e) {
            throw new Exception("Error calling authentication service: " . $e->getMessage(), 3);
        }

        $body = json_decode($response->getBody()); // Assuming the external service returns JSON with verification result
        return $body->verified;
    }
}
?>
