        FILE *input = fopen(va_arg(valist, char*), "r");
        if (input == NULL) {
            printf("Could not open file %s for reading\n", va_arg(valist, char*));
            return -1;
        }

        while (fgets(line, sizeof line, input)) {
            fputs(line, output);
        }

        fclose(input);
    }

    va_end(valist);  /* Clean up */
    fclose(output);

    return 0;
}
```
