// A function to encrypt data using an algorithm specified by an environment variable
const EVP_CIPHER *(*get_cipher())(void) {
    const char* env_var = getenv("LOGGING_ENCRYPTION_ALGORITHM");

    if (strcmp(env_var, "AES-256") == 0) {
        return EVP_aes_256_cbc;
    } else if (strcmp(env_var, "DES") == 0) {
        return EVP_des_cbc;
    } 

    // Default to AES-128 for safety
    return EVP_aes_128_cbc;
}

// Function to encrypt data using the selected cipher and an IV
void encrypt(unsigned char *plaintext, int plaintext_len, unsigned char *key,
             unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;

    int len;
    int ciphertext_len;

    /* Create and initialise the context */
    if(!(ctx = EVP_CIPHER_CTX_new())) {
        // handle errors
    }

    /* Initialise the encryption operation. IMPORTANT - ensure you have a key of 
    * correct length for your cipher e.g AES-256 = 32 bytes */
    if(1 != EVP_EncryptInit_ex(ctx, get_cipher(), NULL, key, iv)) {
        // handle errors
    }

    /* Provide the message to be encrypted, and obtain the encrypted output. 
    * e is the total length of the data encrypted so far */
    if(1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        // handle errors
    }
    ciphertext_len = len;

    /* Finalise the encryption. Further ciphertext bytes may be written at 
    * this stage */
    if(1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        // handle errors
    }
    ciphertext_len += len;

    /* Clean up */
    EVP_CIPHER_CTX_free(ctx);
}
```
