function fetchWithRetry(url, options) {
    let attempts = 0;
    const callFetch = () => {
        return fetch(url, options).catch((err) => {
            if (++attempts < 5) {
                console.log('An error occurred when fetching data:', err);
                // Exponential backoff delay
                return new Promise(resolve => setTimeout(callFetch, 1000 * Math.pow(2, attempts)));
            } else {
