#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char* eps_identification;
    char* nas_header;
    int sgw_id;
} LTE_MME_MESSAGE_T;

LTE_MME_MESSAGE_T** messages = NULL;
size_t messageCount = 0, messageCapacity = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int addMessage(LTE_MME_MESSAGE_T* msg) {
    pthread_mutex_lock(&lock);
    if (messageCount >= messageCapacity) {
        messageCapacity = messageCapacity * 2 + 1;
        messages = realloc(messages, messageCapacity * sizeof(*messages));
        if (!messages) {
            perror("Failed to allocate memory");
            return -1;
        }
    }
    messages[messageCount++] = msg;
    pthread_mutex_unlock(&lock);
    return 0;
}

LTE_MME_MESSAGE_T* getMessage(size_t index) {
    if (index < messageCount) {
        pthread_mutex_lock(&lock);
        LTE_MME_MESSAGE_T* msg = messages[index];
        pthread_mutex_unlock(&lock);
        return msg;
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

void removeMessage(size_t index) {
    if (index < messageCount) {
        pthread_mutex_lock(&lock);
        free(messages[index]);
        for (size_t i = index; i < messageCount - 1; ++i) {
            messages[i] = messages[i + 1];
        }
        --messageCount;
        pthread_mutex_unlock(&lock);
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
}
```

This is a very basic example. Implementing it as described would require a lot more code, and it doesn't cover all aspects you listed like error handling, data source integration, logging mechanism or concurrency level adjustments based on current load. 

