    private static readonly string API_URL = "http://example.com/api"; // replace with actual URL

    private T lastGeneratedValue;
    private T minRange;
    private T maxRange;
    private bool inclusive;

    public DynamicValueGenerator(T seed, bool inclusive) : this(seed, seed, inclusive) { }

    public DynamicValueGenerator(T minRange, T maxRange, bool inclusive)
    {
        if (minRange.CompareTo(maxRange) > 0) throw new ArgumentException("Invalid range");
        this.minRange = minRange;
        this.maxRange = maxRange;
        this.inclusive = inclusive;
    }

    public async Task<T> GetNextValueAsync()
    {
        try
        {
            var response = await client.GetAsync(API_URL); // replace with actual parameters
            response.EnsureSuccessStatusCode(); 

            var seedString = await response.Content.ReadAsStringAsync();
            dynamic deserializedObject;
            try
