                deserializedObject = JsonConvert.DeserializeObject<dynamic>(seedString); // replace with actual structure of the API response
            }
            catch (JsonException e)
            {
                Log.Error("Failed to deserialize object from external API: " + seedString, e);
                deserializedObject = new Random().Next(); // fallback to default random seed generator
            }

            var valueType = typeof(T);
            dynamic convertedValue;

            if (valueType == typeof(int)) 
            {
                convertedValue = Convert.ToInt32(deserializedObject);
            } 
            else if (valueType == typeof(float)) 
            {
                convertedValue = Convert.ToSingle(deserializedObject);
            } 
            else throw new NotSupportedException("Unsupported type");

            lastGeneratedValue = ConstrainAndRound(convertedValue, minRange, maxRange, inclusive);
            Log.Information("Successfully generated value: " + lastGeneratedValue);
        }
        catch (HttpRequestException e) 
        {
            Log.Error("Failed to get seed from external API", e);
            throw;
        }

        return lastGeneratedValue;
    }

