    private readonly AsyncCircuitBreakerPolicy _circuitBreakerPolicy;
    private readonly IMemoryCache _cache;

    public ProductService(IMemoryCache memoryCache)
    {
        _cache = memoryCache;
        _circuitBreakerPolicy = Policy.Handle<Exception>().CircuitBreakerAsync(2, TimeSpan.FromMinutes(1));
    }

    // Cached method for better performance
    [MethodImpl(MethodImplOptions.Synchronized)]
    public async Task<IEnumerable<Product>> GetProducts()
    {
        return await _cache.GetOrCreateAsync("products", entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            return GetProductsImpl();
        });
    }

    private async Task<IEnumerable<Product>> GetProductsImpl()
    {
        var inventoryClient = new RestClient(InventoryApi);
        var weatherClient = new RestClient(WeatherApi);

        // Wrap calls to APIs in the circuit breaker policy
        var inventoryResponse = await _circuitBreakerPolicy.ExecuteAsync(() => inventoryClient.GetAsync<List<Product>>("inventory"));
        var weatherResponse = await _circuitBreakerPolicy.ExecuteAsync(() => weatherClient.GetAsync<Weather>("weather"));

        // Process and return the results
    }
}
