Here is a basic implementation of an Event System:

```go
package main

import (
	"sync"
)

type Event struct {
	// Define your event structure here
}

type Handler func(Event)

type EventManager struct {
	handlers map[string][]Handler
	mu       sync.RWMutex
}

func NewEventManager() *EventManager {
	return &EventManager{
		handlers: make(map[string][]Handler),
	}
}

func (em *EventManager) On(eventName string, handler Handler) {
	em.mu.Lock()
	defer em.mu.Unlock()

	if _, exists := em.handlers[eventName]; !exists {
		em.handlers[eventName] = make([]Handler, 0)
	}
	em.handlers[eventName] = append(em.handlers[eventName], handler)
}

func (em *EventManager) Emit(event Event, eventName string) {
	if handlers, exists := em.handlers[eventName]; exists {
		for _, handler := range handlers {
			// Invoke the handlers concurrently
			go handler(event)
		}
	}
}
```
This is just a basic representation of how you could handle events in Go. It doesn't cover all aspects mentioned in the problem, but it does illustrate some important points like event handling, concurrency and locking for safe operation with multiple goroutines. 

