typedef enum {
    ERROR_SUCCESS = 0,
    ERROR_FILE_NOT_FOUND = -1,
} ErrorCode;

char* file_extension(const char *filename) {
    char *dot = strrchr(filename, '.');
    if(!dot || dot == filename) return "";
    return dot + 1;
}

// Rename a single file
ErrorCode rename_file(const char *oldname, const char *newname) {
    if (rename(oldname, newname)) {
        // Error handling here...
        perror("Rename failed");
        return ERROR_FILE_NOT_FOUND;
    }
    return ERROR_SUCCESS;
}

// Rename all files in a directory
ErrorCode rename_all(const char *path) {
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir (path)) != NULL) {
        while ((ent = readdir (dir)) != NULL) {
            // Skip "." and ".." directories
            if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) continue;

            char oldpath[1024];
            snprintf(oldpath, sizeof(oldpath), "%s/%s", path, ent->d_name);

            // Check if it is a directory or a file
            struct stat st;
            if (stat(oldpath, &st) == 0 && S_ISDIR(st.st_mode)) {
                rename_all(oldpath);  // Recurse into subdirectories
            } else {
                // Use your own renaming logic here...
                char newname[1024];
                snprintf(newname, sizeof(newname), "%s/%s.renamed", path, ent->d_name);

                if (rename_file(oldpath, newname) != ERROR_SUCCESS) {
                    return ERROR_FILE_NOT_FOUND;
                }
            }
        }
        closedir (dir);
    } else {
        perror ("Could not open directory");
        return -1;
    }

    return ERROR_SUCCESS;
}

int main(void) {
    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) != NULL) {
        rename_all(cwd);  // Rename all files in the current directory
    } else {
        perror("Unable to get current working directory");
        return -1;
    }

    return 0;
}
```

