```C
#include <libpq-fe.h>
#include <stdio.h>

PGconn *connectDB(char *user, char *password) {
    const int dbConnParams = 6; 
    PGconn* conn = NULL;

    const char *conninfo[dbConnParams];
    conninfo[0] = "user";
    conninfo[1] = user;
    conninfo[2] = "password";
    conninfo[3] = password;
    conninfo[4] = "hostaddr";
    conninfo[5] = "localhost";

    conn = PQconnectdbParams(conninfo, 0);

    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s",
                PQerrorMessage(conn));
        PQfinish(conn);
        return NULL;
    }

    return conn;
}

char* getEmployeeDetails(PGconn *conn, int supervisorID) {
    const char *sqlStatement = "SELECT name, city, address FROM Employees WHERE supervisor_id = $1";

    PGresult *res = PQexecParams(conn, sqlStatement, 1, NULL, &supervisorID, NULL, NULL, 0);

    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        printf("No data retrieved\n");
        PQclear(res);
        return "";
    }

    int nRows = PQntuples(res); 

    char *result = (char*) malloc(256*sizeof(char));
    strcpy(result, "");

    for (int i = 0; i < nRows; i++) {
        for (int j = 0; j < 3; j++) { 
            strcat(result, PQgetvalue(res, i, j));
            strcat(result, " ");
        }
    }

    PQclear(res);

    return result;
}
```
This C code connects to a PostgreSQL database and retrieves employee details from the Employees table. The function getEmployeeDetails() is designed to fetch details of employees whose supervisor ID matches the provided supervisorID parameter. Please note that this is a basic implementation for educational purposes and does not include many features like error handling, thread safety, and so on.
