```java
public class TransactionProcessor implements Runnable {
    private final BlockingQueue<Transaction> queue;

    public TransactionProcessor(BlockingQueue<Transaction> queue) {
        this.queue = queue;
    }

    public void run() {
        while (true) {
            try {
                Transaction txn = queue.take();
                processTxn(txn);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void processTxn(Transaction txn) {
        // Validate the transaction against business rules and regulations
        if (validateTxn(txn)) {
            // Save the transaction to the database
            saveToDatabase(txn);
        } else {
            // Handle invalid transactions
            handleInvalidTxn(txn);
        }
    }
}
```
