class Octant {
public:
  std::vector<Point*> points;
  float size;
  Octant *children[8]; // or std::array if you prefer

  void Insert(Point &p) {
    // Determine which child the point belongs to.
    int index = GetChildIndex(p);

    // If this octant has no children, it's a leaf node.
    if (!children[0]) {
      points.push_back(&p);

      // Split the octant if it contains too many points.
      if (points.size() > 1 && size / 2 >= MINIMUM_OCTANT_SIZE) {
        for(int i = 0; i < 8; ++i) children[i] = new Octant(size / 2);

        // Redistribute the points among the children.
        while (!points.empty()) {
          Point* p = points.back();
          points.pop_back();

          int index = GetChildIndex(*p);
          children[index]->Insert(*p);
        }

        // Insert the point in the appropriate child octant.
        children[index]->Insert(p);
      }
    } else {
      // The octant is an inner node; insert into the correct child octant.
      children[index]->Insert(p);
    }
  }

  int GetChildIndex(Point &p) {
    // Determine which of the eight children contains this point.
  }
};
