['Implementing this as a command line application in C would involve substantial work and would be too large to be fully covered here, but I can provide you with an example of how it could start in a simplified way. Note that this is not production ready code. A real implementation would require more considerations such as error handling, logging, configuration management, thread pooling for better performance, data validation, etc.

```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <postgresql/libpq-fe.h>

// Define a function to handle database connections
PGconn* connect_to_database(const char *conninfo) {
    PGconn *conn = PQconnectdb(conninfo);

    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
        PQfinish(conn);
        exit(1);
    }

    return conn;
}

// Define a function to compute the average of last two fields and append it to the record
char* process_record(const char *line) {
    // split the line into tokens, count them, then find the penultimate and last tokens
    int num_fields = 0; 
    const char *last = NULL, *penultimate = NULL;

    for (char *token = strtok((char*)line, "\t"); token != NULL; token = strtok(NULL, "\t")) {
        penultimate = last;
        last = token;
        num_fields++;
    }

    // compute the average of the two fields and append it to a new string
    char *new_line = malloc((strlen(line) + 16) * sizeof(char));
    sprintf(new_line, "%s\t%.2f", line, (atof(penultimate) + atof(last)) / 2.0);

    return new_line;
}

// Define the main function to handle file processing and database connection
int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s input.txt output.db conninfo\n", argv[0]);
        exit(1);
    }

    FILE* file = fopen(argv[1], "r");
    if (file == NULL) {
        perror("Error opening the file");
        return 1;
    }

    PGconn *conn = connect_to_database(argv[3]);
    const char* insert = "INSERT INTO output VALUES (%s);";
    char buffer[256];

    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        // process each line and insert the result into the database
        char *processed_line = process_record(buffer);
        sprintf(buffer, insert, processed_line);

        PGresult *res = PQexec(conn, buffer);
        if (PQresultStatus(res) != PGRES_COMMAND_OK) {
            fprintf(stderr, "Failed to execute SQL statement: %s", PQerrorMessage(conn));
            PQclear(res);
            exit(1);
        }

        PQclear(res);
        free(processed_line);
    }

    // cleanup and return
    fclose(file);
    PQfinish(conn);
    return 0;
}
```

This is a simplified example, and doesn't include many of the factors you described such as error handling, logging, concurrency, modularity, command-line interface, or testing. You would also need to install PostgreSQL development libraries for this code to compile and run properly. I would recommend breaking down your problem into smaller tasks, implementing each one separately, then combining them together. This way, you can ensure each part of the application is functioning correctly before moving onto the next piece.
